insert into public.atlas_content (id,slug,content_type,category_slug,title,summary,topic,status,version,audience,permissions,keywords,reading_minutes,metadata,document,is_demo,published_at) values ('article.welcome-atlas','welcome-to-moscatelli-atlas','article','the-house','Welcome to MOSCATELLI Atlas','What Atlas is for, what belongs here and how to distinguish institutional knowledge from live operational work.','Internal terminology','current','0.1-demo','["All internal users"]'::jsonb,'["internal"]'::jsonb,'["Atlas","knowledge","standards","orientation","MainHub"]'::jsonb,4,'{"id":"article.welcome-atlas","slug":"welcome-to-moscatelli-atlas","type":"article","category":"the-house","topic":"Internal terminology","eyebrow":"Orientation","title":"Welcome to MOSCATELLI Atlas","summary":"What Atlas is for, what belongs here and how to distinguish institutional knowledge from live operational work.","keywords":["Atlas","knowledge","standards","orientation","MainHub"],"readingMinutes":4,"owner":"Operations","approver":"Founder","version":"0.1-demo","publishedDate":"2026-08-13","lastReviewed":"2026-08-13","nextReview":"2026-11-13","languageStatus":"English demonstration","status":"current","audience":["All internal users"],"permissions":["internal"],"demo":true}'::jsonb,'{"id":"article.welcome-atlas","slug":"welcome-to-moscatelli-atlas","type":"article","category":"the-house","topic":"Internal terminology","eyebrow":"Orientation","title":"Welcome to MOSCATELLI Atlas","summary":"What Atlas is for, what belongs here and how to distinguish institutional knowledge from live operational work.","keywords":["Atlas","knowledge","standards","orientation","MainHub"],"readingMinutes":4,"owner":"Operations","approver":"Founder","version":"0.1-demo","publishedDate":"2026-08-13","lastReviewed":"2026-08-13","nextReview":"2026-11-13","languageStatus":"English demonstration","status":"current","audience":["All internal users"],"permissions":["internal"],"demo":true,"contentNotice":"Demonstration content for Atlas interface development; not final MOSCATELLI policy.","tableOfContents":true,"sections":[{"heading":"Atlas and MainHub","blocks":[{"type":"paragraph","text":"Atlas is the reference layer: it explains standards, procedures and institutional knowledge. MainHub remains the place for live operational work, current projects and records."},{"type":"callout","label":"Working distinction","text":"If the information should still be useful after the current task has ended, it probably belongs in Atlas. If it represents live work, ownership or a current operational record, it belongs in MainHub."}]},{"heading":"What belongs here","blocks":[{"type":"paragraph","text":"Atlas should contain durable guidance that another team member can rely upon without reconstructing context from messages, meetings or memory."},{"type":"checklist","items":["Standards that define an expected quality threshold","Procedures that should be repeated consistently","Reference material that explains MOSCATELLI terminology or decisions","Learning material that supports onboarding and role development"]}]},{"heading":"How to use an article","blocks":[{"type":"procedure","steps":[{"title":"Confirm the status","text":"Check whether the article is current, under review, superseded or archived."},{"title":"Read the governing context","text":"Use the owner, approver and review dates to understand who maintains the reference."},{"title":"Follow related material","text":"Move to a linked procedure or MainHub destination when the reference points to live work."}]},{"type":"paragraph","text":"Demonstration content in this preview is explicitly labelled and should not be treated as final company policy."}]},{"heading":"Institutional memory","blocks":[{"type":"paragraph","text":"The long-term purpose of Atlas is to reduce dependency on individual memory. A useful knowledge system makes the company easier to operate, teach and improve without making the work feel bureaucratic."}]}],"related":["working-with-standards-at-moscatelli","how-moscatelli-records-decisions"],"mainHubLinks":[]}'::jsonb,true,'2026-08-13') on conflict (id) do update set slug=excluded.slug,content_type=excluded.content_type,category_slug=excluded.category_slug,title=excluded.title,summary=excluded.summary,topic=excluded.topic,status=excluded.status,version=excluded.version,audience=excluded.audience,permissions=excluded.permissions,keywords=excluded.keywords,reading_minutes=excluded.reading_minutes,metadata=excluded.metadata,document=excluded.document,is_demo=excluded.is_demo,published_at=excluded.published_at,updated_at=now();
insert into public.atlas_content (id,slug,content_type,category_slug,title,summary,topic,status,version,audience,permissions,keywords,reading_minutes,metadata,document,is_demo,published_at) values ('article.house-standards','working-with-standards-at-moscatelli','article','the-house','Working with standards at MOSCATELLI','A demonstration reference for how standards should guide decisions without turning judgement into bureaucracy.','Mission and values','under-review','0.1-demo','["All internal users"]'::jsonb,'["internal"]'::jsonb,'["standards","values","decisions","quality"]'::jsonb,5,'{"id":"article.house-standards","slug":"working-with-standards-at-moscatelli","type":"article","category":"the-house","topic":"Mission and values","eyebrow":"The House","title":"Working with standards at MOSCATELLI","summary":"A demonstration reference for how standards should guide decisions without turning judgement into bureaucracy.","keywords":["standards","values","decisions","quality"],"readingMinutes":5,"owner":"Founder","approver":"Founder","version":"0.1-demo","publishedDate":"2026-08-13","lastReviewed":"2026-08-13","nextReview":"2026-11-13","languageStatus":"English demonstration","status":"under-review","audience":["All internal users"],"permissions":["internal"],"demo":true}'::jsonb,'{"id":"article.house-standards","slug":"working-with-standards-at-moscatelli","type":"article","category":"the-house","topic":"Mission and values","eyebrow":"The House","title":"Working with standards at MOSCATELLI","summary":"A demonstration reference for how standards should guide decisions without turning judgement into bureaucracy.","keywords":["standards","values","decisions","quality"],"readingMinutes":5,"owner":"Founder","approver":"Founder","version":"0.1-demo","publishedDate":"2026-08-13","lastReviewed":"2026-08-13","nextReview":"2026-11-13","languageStatus":"English demonstration","status":"under-review","audience":["All internal users"],"permissions":["internal"],"demo":true,"contentNotice":"Demonstration content for Atlas interface development; not final MOSCATELLI policy.","tableOfContents":true,"sections":[{"heading":"Purpose","blocks":[{"type":"paragraph","text":"Standards create a shared quality threshold and a repeatable point of reference. They should support judgement rather than replace it."},{"type":"callout","label":"Principle","text":"A standard should make an important decision clearer. If it only creates paperwork without protecting quality, consistency or accountability, it should be reconsidered."}]},{"heading":"When a standard applies","blocks":[{"type":"paragraph","text":"Use a published standard when the work falls within its stated scope. If circumstances materially differ, record the exception rather than silently ignoring the standard."},{"type":"checklist","items":["Confirm that the current version applies","Identify any material exception before proceeding","Record who approved a departure when one is necessary","Feed recurring exceptions back into the next review"]}]},{"heading":"Standards and judgement","blocks":[{"type":"paragraph","text":"Luxury quality depends on discernment as well as consistency. A standard defines the floor and the shared vocabulary; creative and commercial judgement still determine the best answer within that framework."}]}],"related":["welcome-to-moscatelli-atlas","how-moscatelli-records-decisions"],"mainHubLinks":[]}'::jsonb,true,'2026-08-13') on conflict (id) do update set slug=excluded.slug,content_type=excluded.content_type,category_slug=excluded.category_slug,title=excluded.title,summary=excluded.summary,topic=excluded.topic,status=excluded.status,version=excluded.version,audience=excluded.audience,permissions=excluded.permissions,keywords=excluded.keywords,reading_minutes=excluded.reading_minutes,metadata=excluded.metadata,document=excluded.document,is_demo=excluded.is_demo,published_at=excluded.published_at,updated_at=now();
insert into public.atlas_content (id,slug,content_type,category_slug,title,summary,topic,status,version,audience,permissions,keywords,reading_minutes,metadata,document,is_demo,published_at) values ('article.tone-of-voice','introduction-to-moscatelli-tone-of-voice','article','brand','Introduction to MOSCATELLI’s tone of voice','A practical introduction to restraint, clarity and authority in internal and external MOSCATELLI writing.','Tone of voice','current','0.1-demo','["All internal users"]'::jsonb,'["internal"]'::jsonb,'["brand","tone","voice","writing","communication"]'::jsonb,7,'{"id":"article.tone-of-voice","slug":"introduction-to-moscatelli-tone-of-voice","type":"article","category":"brand","topic":"Tone of voice","eyebrow":"Brand standard","title":"Introduction to MOSCATELLI’s tone of voice","summary":"A practical introduction to restraint, clarity and authority in internal and external MOSCATELLI writing.","keywords":["brand","tone","voice","writing","communication"],"readingMinutes":7,"owner":"Creative Direction","approver":"Founder","version":"0.1-demo","publishedDate":"2026-08-13","lastReviewed":"2026-08-13","nextReview":"2026-10-13","languageStatus":"English demonstration","status":"current","audience":["All internal users"],"permissions":["internal"],"demo":true}'::jsonb,'{"id":"article.tone-of-voice","slug":"introduction-to-moscatelli-tone-of-voice","type":"article","category":"brand","topic":"Tone of voice","eyebrow":"Brand standard","title":"Introduction to MOSCATELLI’s tone of voice","summary":"A practical introduction to restraint, clarity and authority in internal and external MOSCATELLI writing.","keywords":["brand","tone","voice","writing","communication"],"readingMinutes":7,"owner":"Creative Direction","approver":"Founder","version":"0.1-demo","publishedDate":"2026-08-13","lastReviewed":"2026-08-13","nextReview":"2026-10-13","languageStatus":"English demonstration","status":"current","audience":["All internal users"],"permissions":["internal"],"demo":true,"contentNotice":"Demonstration content for Atlas interface development; not final MOSCATELLI policy.","tableOfContents":true,"sections":[{"heading":"Principles","blocks":[{"type":"paragraph","text":"Prefer precise language, calm confidence and useful context. Avoid inflated claims, filler and unnecessary informality."},{"type":"list","items":["Say exactly what is known and what is not.","Use restraint instead of superlatives.","Write for comprehension before ornament.","Preserve warmth without becoming casual or verbose."]}]},{"heading":"Authority without noise","blocks":[{"type":"paragraph","text":"MOSCATELLI should not need to insist that something is exceptional. The writing should communicate confidence through specificity, proportion and control."},{"type":"callout","label":"Avoid","text":"Generic luxury language such as “unparalleled”, “timeless elegance” or “the finest” should not substitute for concrete information."}]},{"heading":"Internal writing","blocks":[{"type":"paragraph","text":"Internal communication can be more direct than public copy, but it should remain clear enough that another person can understand the decision, action and context later."},{"type":"procedure","steps":[{"title":"Lead with the point","text":"State the decision, request or change early."},{"title":"Add material context","text":"Include only the information needed to understand why it matters."},{"title":"Make ownership explicit","text":"When action is required, identify who owns it and when it is expected."}]}]},{"heading":"Review test","blocks":[{"type":"checklist","items":["Is every claim supportable?","Could the sentence be shorter without losing meaning?","Does the tone sound composed rather than promotional?","Would the wording still make sense outside the immediate conversation?"]}]}],"related":["photography-approval-checklist","internal-communication-standards"],"mainHubLinks":[]}'::jsonb,true,'2026-08-13') on conflict (id) do update set slug=excluded.slug,content_type=excluded.content_type,category_slug=excluded.category_slug,title=excluded.title,summary=excluded.summary,topic=excluded.topic,status=excluded.status,version=excluded.version,audience=excluded.audience,permissions=excluded.permissions,keywords=excluded.keywords,reading_minutes=excluded.reading_minutes,metadata=excluded.metadata,document=excluded.document,is_demo=excluded.is_demo,published_at=excluded.published_at,updated_at=now();
insert into public.atlas_content (id,slug,content_type,category_slug,title,summary,topic,status,version,audience,permissions,keywords,reading_minutes,metadata,document,is_demo,published_at) values ('article.photography-approval','photography-approval-checklist','article','brand','Photography approval checklist','The visual and technical points to review before an image is treated as approved MOSCATELLI material.','Photography','current','0.1-demo','["Creative","Marketing","Operations"]'::jsonb,'["internal"]'::jsonb,'["photography","image","approval","resolution","brand"]'::jsonb,6,'{"id":"article.photography-approval","slug":"photography-approval-checklist","type":"article","category":"brand","topic":"Photography","eyebrow":"Brand checklist","title":"Photography approval checklist","summary":"The visual and technical points to review before an image is treated as approved MOSCATELLI material.","keywords":["photography","image","approval","resolution","brand"],"readingMinutes":6,"owner":"Creative Direction","approver":"Founder","version":"0.1-demo","publishedDate":"2026-08-13","lastReviewed":"2026-08-13","nextReview":"2026-10-13","languageStatus":"English demonstration","status":"current","audience":["Creative","Marketing","Operations"],"permissions":["internal"],"demo":true}'::jsonb,'{"id":"article.photography-approval","slug":"photography-approval-checklist","type":"article","category":"brand","topic":"Photography","eyebrow":"Brand checklist","title":"Photography approval checklist","summary":"The visual and technical points to review before an image is treated as approved MOSCATELLI material.","keywords":["photography","image","approval","resolution","brand"],"readingMinutes":6,"owner":"Creative Direction","approver":"Founder","version":"0.1-demo","publishedDate":"2026-08-13","lastReviewed":"2026-08-13","nextReview":"2026-10-13","languageStatus":"English demonstration","status":"current","audience":["Creative","Marketing","Operations"],"permissions":["internal"],"demo":true,"contentNotice":"Demonstration content for Atlas interface development; not final MOSCATELLI policy.","tableOfContents":true,"sections":[{"heading":"Before approval","blocks":[{"type":"paragraph","text":"Confirm subject, crop, resolution, colour treatment, rights status and intended use before treating an image as approved material."},{"type":"checklist","items":["Composition supports the intended hierarchy and crop","Focus and detail are sufficient at the intended output size","Colour and contrast remain natural to the art direction","No distracting artefacts, accidental branding or unresolved retouching","Usage rights and source are documented where required"]}]},{"heading":"Technical review","blocks":[{"type":"paragraph","text":"Technical adequacy depends on the intended placement. A social crop, a full-width website image and print material may require different dimensions and export treatment."},{"type":"callout","label":"Do not approve by appearance alone","text":"A visually pleasing preview can still be unsuitable if the source file is too small, excessively compressed or missing the required usage information."}]},{"heading":"Creative review","blocks":[{"type":"list","items":["The image feels consistent with the approved MOSCATELLI visual language.","Lighting, materials and skin or product tones remain believable.","The frame does not depend on fashionable effects that overwhelm the subject.","The crop preserves intentional negative space where copy may be required."]}]},{"heading":"Record the decision","blocks":[{"type":"paragraph","text":"When an image is approved, keep the approved source and the decision context together so that later teams do not need to determine again which version is authoritative."}]}],"related":["introduction-to-moscatelli-tone-of-voice","product-naming-standards"],"mainHubLinks":[]}'::jsonb,true,'2026-08-13') on conflict (id) do update set slug=excluded.slug,content_type=excluded.content_type,category_slug=excluded.category_slug,title=excluded.title,summary=excluded.summary,topic=excluded.topic,status=excluded.status,version=excluded.version,audience=excluded.audience,permissions=excluded.permissions,keywords=excluded.keywords,reading_minutes=excluded.reading_minutes,metadata=excluded.metadata,document=excluded.document,is_demo=excluded.is_demo,published_at=excluded.published_at,updated_at=now();
insert into public.atlas_content (id,slug,content_type,category_slug,title,summary,topic,status,version,audience,permissions,keywords,reading_minutes,metadata,document,is_demo,published_at) values ('article.product-naming','product-naming-standards','article','products-and-quality','Product naming standards','A demonstration framework for creating product names that remain coherent, distinctive and usable across records and communications.','Product naming','current','0.1-demo','["Creative","Operations","Marketing"]'::jsonb,'["internal"]'::jsonb,'["product","naming","standards","SKU","collection"]'::jsonb,6,'{"id":"article.product-naming","slug":"product-naming-standards","type":"article","category":"products-and-quality","topic":"Product naming","eyebrow":"Product standard","title":"Product naming standards","summary":"A demonstration framework for creating product names that remain coherent, distinctive and usable across records and communications.","keywords":["product","naming","standards","SKU","collection"],"readingMinutes":6,"owner":"Creative Direction","approver":"Founder","version":"0.1-demo","publishedDate":"2026-08-13","lastReviewed":"2026-08-13","nextReview":"2026-10-13","languageStatus":"English demonstration","status":"current","audience":["Creative","Operations","Marketing"],"permissions":["internal"],"demo":true}'::jsonb,'{"id":"article.product-naming","slug":"product-naming-standards","type":"article","category":"products-and-quality","topic":"Product naming","eyebrow":"Product standard","title":"Product naming standards","summary":"A demonstration framework for creating product names that remain coherent, distinctive and usable across records and communications.","keywords":["product","naming","standards","SKU","collection"],"readingMinutes":6,"owner":"Creative Direction","approver":"Founder","version":"0.1-demo","publishedDate":"2026-08-13","lastReviewed":"2026-08-13","nextReview":"2026-10-13","languageStatus":"English demonstration","status":"current","audience":["Creative","Operations","Marketing"],"permissions":["internal"],"demo":true,"contentNotice":"Demonstration content for Atlas interface development; not final MOSCATELLI policy.","tableOfContents":true,"sections":[{"heading":"Naming test","blocks":[{"type":"paragraph","text":"A product name should be distinctive enough to identify the object while remaining consistent across editorial, operational and commercial contexts."},{"type":"checklist","items":["Easy to read and pronounce in the principal operating languages","Distinct from an existing product or project name","Appropriate to the product rather than dependent on temporary campaign language","Usable in internal records without ambiguity"]}]},{"heading":"Working name and final name","blocks":[{"type":"paragraph","text":"Development names may be practical and temporary. A final product name should only replace them once the change can be reflected consistently across the relevant records."},{"type":"callout","label":"Consistency","text":"Avoid allowing different teams to use competing names for the same product. If a name changes, the previous reference should remain traceable."}]},{"heading":"Approval sequence","blocks":[{"type":"procedure","steps":[{"title":"Check the existing catalogue","text":"Confirm that the proposed name does not create an avoidable collision."},{"title":"Review meaning and use","text":"Consider pronunciation, connotation and how the name appears in editorial and operational contexts."},{"title":"Approve once","text":"Record the final decision and update dependent references from a single source of truth."}]}]}],"related":["supplier-sample-review-procedure","photography-approval-checklist"],"mainHubLinks":[]}'::jsonb,true,'2026-08-13') on conflict (id) do update set slug=excluded.slug,content_type=excluded.content_type,category_slug=excluded.category_slug,title=excluded.title,summary=excluded.summary,topic=excluded.topic,status=excluded.status,version=excluded.version,audience=excluded.audience,permissions=excluded.permissions,keywords=excluded.keywords,reading_minutes=excluded.reading_minutes,metadata=excluded.metadata,document=excluded.document,is_demo=excluded.is_demo,published_at=excluded.published_at,updated_at=now();
insert into public.atlas_content (id,slug,content_type,category_slug,title,summary,topic,status,version,audience,permissions,keywords,reading_minutes,metadata,document,is_demo,published_at) values ('article.sample-review','supplier-sample-review-procedure','article','products-and-quality','Supplier sample review procedure','A repeatable demonstration process for inspecting, documenting and responding to a supplier sample.','Sample stages','current','0.1-demo','["Creative","Operations"]'::jsonb,'["internal"]'::jsonb,'["supplier","sample","prototype","review","quality"]'::jsonb,8,'{"id":"article.sample-review","slug":"supplier-sample-review-procedure","type":"article","category":"products-and-quality","topic":"Sample stages","eyebrow":"Quality procedure","title":"Supplier sample review procedure","summary":"A repeatable demonstration process for inspecting, documenting and responding to a supplier sample.","keywords":["supplier","sample","prototype","review","quality"],"readingMinutes":8,"owner":"Operations","approver":"Founder","version":"0.1-demo","publishedDate":"2026-08-13","lastReviewed":"2026-08-13","nextReview":"2026-10-13","languageStatus":"English demonstration","status":"current","audience":["Creative","Operations"],"permissions":["internal"],"demo":true}'::jsonb,'{"id":"article.sample-review","slug":"supplier-sample-review-procedure","type":"article","category":"products-and-quality","topic":"Sample stages","eyebrow":"Quality procedure","title":"Supplier sample review procedure","summary":"A repeatable demonstration process for inspecting, documenting and responding to a supplier sample.","keywords":["supplier","sample","prototype","review","quality"],"readingMinutes":8,"owner":"Operations","approver":"Founder","version":"0.1-demo","publishedDate":"2026-08-13","lastReviewed":"2026-08-13","nextReview":"2026-10-13","languageStatus":"English demonstration","status":"current","audience":["Creative","Operations"],"permissions":["internal"],"demo":true,"contentNotice":"Demonstration content for Atlas interface development; not final MOSCATELLI policy.","tableOfContents":true,"sections":[{"heading":"Before inspection","blocks":[{"type":"paragraph","text":"Record when the sample arrived and identify the specification, quotation or previous sample against which it should be reviewed."},{"type":"checklist","items":["Correct supplier and project","Sample stage is known","Relevant specification or previous reference is available","Packaging and transit condition are recorded before disposal"]}]},{"heading":"Review sequence","blocks":[{"type":"procedure","steps":[{"title":"Inspect objectively","text":"Check dimensions, materials, construction, finish and any agreed measurable requirements."},{"title":"Photograph evidence","text":"Capture both the overall sample and details that explain any deviation or requested revision."},{"title":"Separate fact from preference","text":"Distinguish specification failures from creative refinements so the supplier can understand the priority."},{"title":"Consolidate feedback","text":"Send one coherent revision request rather than fragmented comments from multiple channels."}]}]},{"heading":"Classifying findings","blocks":[{"type":"callout","label":"Useful distinction","text":"A defect is not the same as a design change. Recording the distinction improves supplier accountability and preserves a clearer development history."},{"type":"list","items":["Critical: prevents approval or safe use","Material: meaningful deviation from specification or intended quality","Minor: acceptable for the stage but worth monitoring","Creative revision: requested change rather than supplier non-conformity"]}]},{"heading":"Close the review","blocks":[{"type":"paragraph","text":"Record the outcome, the requested next sample or action, and any agreed timing. Keep the evidence with the development record so the next review can compare like with like."}]}],"related":["reviewing-a-supplier-quotation","product-naming-standards"],"mainHubLinks":[]}'::jsonb,true,'2026-08-13') on conflict (id) do update set slug=excluded.slug,content_type=excluded.content_type,category_slug=excluded.category_slug,title=excluded.title,summary=excluded.summary,topic=excluded.topic,status=excluded.status,version=excluded.version,audience=excluded.audience,permissions=excluded.permissions,keywords=excluded.keywords,reading_minutes=excluded.reading_minutes,metadata=excluded.metadata,document=excluded.document,is_demo=excluded.is_demo,published_at=excluded.published_at,updated_at=now();
insert into public.atlas_content (id,slug,content_type,category_slug,title,summary,topic,status,version,audience,permissions,keywords,reading_minutes,metadata,document,is_demo,published_at) values ('article.decision-records','how-moscatelli-records-decisions','article','operations','How MOSCATELLI records decisions','Where a meaningful decision should be recorded, what context to preserve and how to leave a useful institutional trail.','Records','current','0.1-demo','["All internal users"]'::jsonb,'["internal"]'::jsonb,'["record","decision","MainHub","documentation","history"]'::jsonb,5,'{"id":"article.decision-records","slug":"how-moscatelli-records-decisions","type":"article","category":"operations","topic":"Records","eyebrow":"Operating practice","title":"How MOSCATELLI records decisions","summary":"Where a meaningful decision should be recorded, what context to preserve and how to leave a useful institutional trail.","keywords":["record","decision","MainHub","documentation","history"],"readingMinutes":5,"owner":"Operations","approver":"Founder","version":"0.1-demo","publishedDate":"2026-08-13","lastReviewed":"2026-08-13","nextReview":"2026-11-13","languageStatus":"English demonstration","status":"current","audience":["All internal users"],"permissions":["internal"],"demo":true}'::jsonb,'{"id":"article.decision-records","slug":"how-moscatelli-records-decisions","type":"article","category":"operations","topic":"Records","eyebrow":"Operating practice","title":"How MOSCATELLI records decisions","summary":"Where a meaningful decision should be recorded, what context to preserve and how to leave a useful institutional trail.","keywords":["record","decision","MainHub","documentation","history"],"readingMinutes":5,"owner":"Operations","approver":"Founder","version":"0.1-demo","publishedDate":"2026-08-13","lastReviewed":"2026-08-13","nextReview":"2026-11-13","languageStatus":"English demonstration","status":"current","audience":["All internal users"],"permissions":["internal"],"demo":true,"contentNotice":"Demonstration content for Atlas interface development; not final MOSCATELLI policy.","tableOfContents":true,"sections":[{"heading":"Record the why","blocks":[{"type":"paragraph","text":"A useful decision record preserves the conclusion, owner, date and the material reasoning or constraint that explains why the decision was made."},{"type":"callout","label":"The test","text":"Someone who was not in the room should be able to understand what changed, who decided it and why the decision made sense at the time."}]},{"heading":"What deserves a record","blocks":[{"type":"checklist","items":["A change to an agreed product, supplier or launch direction","An exception to a published standard","A material financial or contractual commitment","A decision likely to be questioned or revisited later","A conclusion that changes another team member’s work"]}]},{"heading":"Minimum decision note","blocks":[{"type":"procedure","steps":[{"title":"State the decision","text":"Write the conclusion in one clear sentence."},{"title":"Preserve context","text":"Record the constraint, evidence or trade-off that materially shaped it."},{"title":"Name ownership","text":"Record the decision owner and any person responsible for the next action."},{"title":"Link the live work","text":"When relevant, connect the decision record to the MainHub item it affects."}]}]}],"related":["file-organisation-and-naming","working-with-standards-at-moscatelli"],"mainHubLinks":[]}'::jsonb,true,'2026-08-13') on conflict (id) do update set slug=excluded.slug,content_type=excluded.content_type,category_slug=excluded.category_slug,title=excluded.title,summary=excluded.summary,topic=excluded.topic,status=excluded.status,version=excluded.version,audience=excluded.audience,permissions=excluded.permissions,keywords=excluded.keywords,reading_minutes=excluded.reading_minutes,metadata=excluded.metadata,document=excluded.document,is_demo=excluded.is_demo,published_at=excluded.published_at,updated_at=now();
insert into public.atlas_content (id,slug,content_type,category_slug,title,summary,topic,status,version,audience,permissions,keywords,reading_minutes,metadata,document,is_demo,published_at) values ('article.file-organisation','file-organisation-and-naming','article','operations','File organisation and naming','A demonstration convention for keeping project material findable, version-aware and understandable to another team member.','File organisation','under-review','0.1-demo','["All internal users"]'::jsonb,'["internal"]'::jsonb,'["files","folders","naming","version","records"]'::jsonb,5,'{"id":"article.file-organisation","slug":"file-organisation-and-naming","type":"article","category":"operations","topic":"File organisation","eyebrow":"Operating standard","title":"File organisation and naming","summary":"A demonstration convention for keeping project material findable, version-aware and understandable to another team member.","keywords":["files","folders","naming","version","records"],"readingMinutes":5,"owner":"Operations","approver":"Founder","version":"0.1-demo","publishedDate":"2026-08-13","lastReviewed":"2026-08-13","nextReview":"2026-11-13","languageStatus":"English demonstration","status":"under-review","audience":["All internal users"],"permissions":["internal"],"demo":true}'::jsonb,'{"id":"article.file-organisation","slug":"file-organisation-and-naming","type":"article","category":"operations","topic":"File organisation","eyebrow":"Operating standard","title":"File organisation and naming","summary":"A demonstration convention for keeping project material findable, version-aware and understandable to another team member.","keywords":["files","folders","naming","version","records"],"readingMinutes":5,"owner":"Operations","approver":"Founder","version":"0.1-demo","publishedDate":"2026-08-13","lastReviewed":"2026-08-13","nextReview":"2026-11-13","languageStatus":"English demonstration","status":"under-review","audience":["All internal users"],"permissions":["internal"],"demo":true,"contentNotice":"Demonstration content for Atlas interface development; not final MOSCATELLI policy.","tableOfContents":true,"sections":[{"heading":"Findability","blocks":[{"type":"paragraph","text":"Names should help another person understand the subject, version and purpose without opening every file."},{"type":"callout","label":"Rule of thumb","text":"Optimise names for the colleague who did not create the file, not for the person who already knows where it is."}]},{"heading":"Naming pattern","blocks":[{"type":"paragraph","text":"Use stable project or subject language first, followed by the specific asset or purpose and a meaningful version or date only when it helps distinguish working states."},{"type":"list","items":["Prefer words over unexplained personal abbreviations.","Avoid “final-final”, “new” and other labels that lose meaning over time.","Do not encode sensitive information in a filename merely for convenience.","Keep approved and working files distinguishable."]}]},{"heading":"Version discipline","blocks":[{"type":"paragraph","text":"When a file becomes authoritative, the location and status should make that clear. Working duplicates should not be able to compete silently with an approved source."}]}],"related":["how-moscatelli-records-decisions","mainhub-access-troubleshooting"],"mainHubLinks":[]}'::jsonb,true,'2026-08-13') on conflict (id) do update set slug=excluded.slug,content_type=excluded.content_type,category_slug=excluded.category_slug,title=excluded.title,summary=excluded.summary,topic=excluded.topic,status=excluded.status,version=excluded.version,audience=excluded.audience,permissions=excluded.permissions,keywords=excluded.keywords,reading_minutes=excluded.reading_minutes,metadata=excluded.metadata,document=excluded.document,is_demo=excluded.is_demo,published_at=excluded.published_at,updated_at=now();
insert into public.atlas_content (id,slug,content_type,category_slug,title,summary,topic,status,version,audience,permissions,keywords,reading_minutes,metadata,document,is_demo,published_at) values ('article.quotation-review','reviewing-a-supplier-quotation','article','suppliers','Reviewing a supplier quotation','What to verify before a quotation is treated as comparable, complete and ready for a commercial decision.','Quotations','current','0.1-demo','["Operations","Founder"]'::jsonb,'["internal"]'::jsonb,'["supplier","vendor","quotation","quote","cost","MOQ"]'::jsonb,7,'{"id":"article.quotation-review","slug":"reviewing-a-supplier-quotation","type":"article","category":"suppliers","topic":"Quotations","eyebrow":"Supplier procedure","title":"Reviewing a supplier quotation","summary":"What to verify before a quotation is treated as comparable, complete and ready for a commercial decision.","keywords":["supplier","vendor","quotation","quote","cost","MOQ"],"readingMinutes":7,"owner":"Operations","approver":"Founder","version":"0.1-demo","publishedDate":"2026-08-13","lastReviewed":"2026-08-13","nextReview":"2026-10-13","languageStatus":"English demonstration","status":"current","audience":["Operations","Founder"],"permissions":["internal"],"demo":true}'::jsonb,'{"id":"article.quotation-review","slug":"reviewing-a-supplier-quotation","type":"article","category":"suppliers","topic":"Quotations","eyebrow":"Supplier procedure","title":"Reviewing a supplier quotation","summary":"What to verify before a quotation is treated as comparable, complete and ready for a commercial decision.","keywords":["supplier","vendor","quotation","quote","cost","MOQ"],"readingMinutes":7,"owner":"Operations","approver":"Founder","version":"0.1-demo","publishedDate":"2026-08-13","lastReviewed":"2026-08-13","nextReview":"2026-10-13","languageStatus":"English demonstration","status":"current","audience":["Operations","Founder"],"permissions":["internal"],"demo":true,"contentNotice":"Demonstration content for Atlas interface development; not final MOSCATELLI policy.","tableOfContents":true,"sections":[{"heading":"Comparable inputs","blocks":[{"type":"paragraph","text":"Confirm material, dimensions, quantity, currency, taxes, shipping assumptions, sample costs, lead time and payment terms before comparing quotations."},{"type":"checklist","items":["Material and specification match the brief","Quantity and MOQ are explicit","Currency and tax basis are clear","Sampling and tooling costs are separated where relevant","Freight, Incoterms or delivery assumptions are stated","Lead time begins from a defined event","Payment schedule is understood"]}]},{"heading":"Normalise before comparing","blocks":[{"type":"paragraph","text":"Two headline unit prices may not be comparable if one excludes tooling, finishing, packing or transport. Convert quotations into the same commercial frame before drawing a conclusion."},{"type":"callout","label":"Commercial caution","text":"The lowest unit price is not necessarily the lowest total cost or the lowest operational risk."}]},{"heading":"Questions back to the supplier","blocks":[{"type":"procedure","steps":[{"title":"Consolidate gaps","text":"Gather missing or ambiguous points into one clear request."},{"title":"Reference the exact quote","text":"Use the quotation date or identifier so both parties are discussing the same document."},{"title":"Preserve revisions","text":"Keep the revised quotation rather than silently replacing the earlier commercial history."}]}]}],"related":["supplier-sample-review-procedure","recording-a-training-expense"],"mainHubLinks":[]}'::jsonb,true,'2026-08-13') on conflict (id) do update set slug=excluded.slug,content_type=excluded.content_type,category_slug=excluded.category_slug,title=excluded.title,summary=excluded.summary,topic=excluded.topic,status=excluded.status,version=excluded.version,audience=excluded.audience,permissions=excluded.permissions,keywords=excluded.keywords,reading_minutes=excluded.reading_minutes,metadata=excluded.metadata,document=excluded.document,is_demo=excluded.is_demo,published_at=excluded.published_at,updated_at=now();
insert into public.atlas_content (id,slug,content_type,category_slug,title,summary,topic,status,version,audience,permissions,keywords,reading_minutes,metadata,document,is_demo,published_at) values ('article.training-expense','recording-a-training-expense','article','finance-and-administration','Recording a training expense','A demonstration administrative procedure for preserving the invoice, purpose, currency and internal approval of training expenditure.','Training costs','current','0.1-demo','["Founder","Operations"]'::jsonb,'["finance-guidance"]'::jsonb,'["training","expense","cost","invoice","receipt","finance"]'::jsonb,6,'{"id":"article.training-expense","slug":"recording-a-training-expense","type":"article","category":"finance-and-administration","topic":"Training costs","eyebrow":"Finance guidance","title":"Recording a training expense","summary":"A demonstration administrative procedure for preserving the invoice, purpose, currency and internal approval of training expenditure.","keywords":["training","expense","cost","invoice","receipt","finance"],"readingMinutes":6,"owner":"Finance","approver":"Founder","version":"0.1-demo","publishedDate":"2026-08-13","lastReviewed":"2026-08-13","nextReview":"2026-10-13","languageStatus":"English demonstration","status":"current","audience":["Founder","Operations"],"permissions":["finance-guidance"],"demo":true}'::jsonb,'{"id":"article.training-expense","slug":"recording-a-training-expense","type":"article","category":"finance-and-administration","topic":"Training costs","eyebrow":"Finance guidance","title":"Recording a training expense","summary":"A demonstration administrative procedure for preserving the invoice, purpose, currency and internal approval of training expenditure.","keywords":["training","expense","cost","invoice","receipt","finance"],"readingMinutes":6,"owner":"Finance","approver":"Founder","version":"0.1-demo","publishedDate":"2026-08-13","lastReviewed":"2026-08-13","nextReview":"2026-10-13","languageStatus":"English demonstration","status":"current","audience":["Founder","Operations"],"permissions":["finance-guidance"],"demo":true,"contentNotice":"Demonstration content for Atlas interface development; not final MOSCATELLI policy.","tableOfContents":true,"sections":[{"heading":"Minimum record","blocks":[{"type":"paragraph","text":"Preserve the supplier, purpose, amount, currency, invoice or receipt, date and any internal approval reference required by the eventual finance process."},{"type":"checklist","items":["Supplier or teacher name","Training purpose and participant","Gross amount and currency","Invoice, receipt or equivalent evidence","Payment date or due date","Internal approval or budget context where applicable"]}]},{"heading":"Currency and conversion","blocks":[{"type":"paragraph","text":"Record the original transaction currency. If an internal report later requires conversion, the converted amount should not erase the source value or the basis used."},{"type":"callout","label":"Demonstration only","text":"The exact accounting and tax treatment will be defined with professional advice and production finance procedures. This article currently validates the Atlas information structure only."}]},{"heading":"Why training was purchased","blocks":[{"type":"paragraph","text":"A short purpose note helps distinguish role-related development from other expenditure and makes later review of training investment more meaningful."}]}],"related":["reviewing-a-supplier-quotation","how-moscatelli-records-decisions"],"mainHubLinks":[]}'::jsonb,true,'2026-08-13') on conflict (id) do update set slug=excluded.slug,content_type=excluded.content_type,category_slug=excluded.category_slug,title=excluded.title,summary=excluded.summary,topic=excluded.topic,status=excluded.status,version=excluded.version,audience=excluded.audience,permissions=excluded.permissions,keywords=excluded.keywords,reading_minutes=excluded.reading_minutes,metadata=excluded.metadata,document=excluded.document,is_demo=excluded.is_demo,published_at=excluded.published_at,updated_at=now();
insert into public.atlas_content (id,slug,content_type,category_slug,title,summary,topic,status,version,audience,permissions,keywords,reading_minutes,metadata,document,is_demo,published_at) values ('article.communication-standards','internal-communication-standards','article','people','Internal communication standards','A demonstration guide to concise updates, ownership, context and appropriate use of synchronous versus asynchronous communication.','Communication standards','current','0.1-demo','["All internal users"]'::jsonb,'["internal"]'::jsonb,'["people","team","staff","communication","Slack","email"]'::jsonb,6,'{"id":"article.communication-standards","slug":"internal-communication-standards","type":"article","category":"people","topic":"Communication standards","eyebrow":"People standard","title":"Internal communication standards","summary":"A demonstration guide to concise updates, ownership, context and appropriate use of synchronous versus asynchronous communication.","keywords":["people","team","staff","communication","Slack","email"],"readingMinutes":6,"owner":"Operations","approver":"Founder","version":"0.1-demo","publishedDate":"2026-08-13","lastReviewed":"2026-08-13","nextReview":"2026-11-13","languageStatus":"English demonstration","status":"current","audience":["All internal users"],"permissions":["internal"],"demo":true}'::jsonb,'{"id":"article.communication-standards","slug":"internal-communication-standards","type":"article","category":"people","topic":"Communication standards","eyebrow":"People standard","title":"Internal communication standards","summary":"A demonstration guide to concise updates, ownership, context and appropriate use of synchronous versus asynchronous communication.","keywords":["people","team","staff","communication","Slack","email"],"readingMinutes":6,"owner":"Operations","approver":"Founder","version":"0.1-demo","publishedDate":"2026-08-13","lastReviewed":"2026-08-13","nextReview":"2026-11-13","languageStatus":"English demonstration","status":"current","audience":["All internal users"],"permissions":["internal"],"demo":true,"contentNotice":"Demonstration content for Atlas interface development; not final MOSCATELLI policy.","tableOfContents":true,"sections":[{"heading":"Useful updates","blocks":[{"type":"paragraph","text":"State what changed, what is needed, who owns the next action and when another update is expected when timing matters."},{"type":"checklist","items":["Lead with the material update","Separate facts from assumptions","Name the owner of the next action","Include a deadline only when one is real","Link the relevant source instead of duplicating it"]}]},{"heading":"Choose the channel","blocks":[{"type":"paragraph","text":"Use asynchronous communication by default when the subject can be understood and resolved without a meeting. Use a call when nuance, speed or active collaboration materially improves the result."},{"type":"callout","label":"After a call","text":"If the conversation creates a decision, commitment or change that matters later, preserve the relevant conclusion in the appropriate written record."}]},{"heading":"Escalation without noise","blocks":[{"type":"paragraph","text":"Escalation should describe the blocker, consequence and requested decision. Adding more recipients without clarifying the need rarely improves the outcome."}]}],"related":["how-moscatelli-records-decisions","introduction-to-moscatelli-tone-of-voice"],"mainHubLinks":[]}'::jsonb,true,'2026-08-13') on conflict (id) do update set slug=excluded.slug,content_type=excluded.content_type,category_slug=excluded.category_slug,title=excluded.title,summary=excluded.summary,topic=excluded.topic,status=excluded.status,version=excluded.version,audience=excluded.audience,permissions=excluded.permissions,keywords=excluded.keywords,reading_minutes=excluded.reading_minutes,metadata=excluded.metadata,document=excluded.document,is_demo=excluded.is_demo,published_at=excluded.published_at,updated_at=now();
insert into public.atlas_content (id,slug,content_type,category_slug,title,summary,topic,status,version,audience,permissions,keywords,reading_minutes,metadata,document,is_demo,published_at) values ('article.mainhub-access','mainhub-access-troubleshooting','article','systems','MainHub access troubleshooting','A demonstration first-response checklist for common access problems before a technical issue is escalated.','MainHub','current','0.1-demo','["All internal users"]'::jsonb,'["internal"]'::jsonb,'["MainHub","login","sign in","access","password","troubleshooting"]'::jsonb,5,'{"id":"article.mainhub-access","slug":"mainhub-access-troubleshooting","type":"article","category":"systems","topic":"MainHub","eyebrow":"Systems guide","title":"MainHub access troubleshooting","summary":"A demonstration first-response checklist for common access problems before a technical issue is escalated.","keywords":["MainHub","login","sign in","access","password","troubleshooting"],"readingMinutes":5,"owner":"Operations","approver":"Founder","version":"0.1-demo","publishedDate":"2026-08-13","lastReviewed":"2026-08-13","nextReview":"2026-10-13","languageStatus":"English demonstration","status":"current","audience":["All internal users"],"permissions":["internal"],"demo":true}'::jsonb,'{"id":"article.mainhub-access","slug":"mainhub-access-troubleshooting","type":"article","category":"systems","topic":"MainHub","eyebrow":"Systems guide","title":"MainHub access troubleshooting","summary":"A demonstration first-response checklist for common access problems before a technical issue is escalated.","keywords":["MainHub","login","sign in","access","password","troubleshooting"],"readingMinutes":5,"owner":"Operations","approver":"Founder","version":"0.1-demo","publishedDate":"2026-08-13","lastReviewed":"2026-08-13","nextReview":"2026-10-13","languageStatus":"English demonstration","status":"current","audience":["All internal users"],"permissions":["internal"],"demo":true,"contentNotice":"Demonstration content for Atlas interface development; not final MOSCATELLI policy.","tableOfContents":true,"sections":[{"heading":"First checks","blocks":[{"type":"paragraph","text":"Confirm the correct account, connectivity, browser state and whether the issue is isolated before escalating with a concise description of what was tested."},{"type":"checklist","items":["Correct MOSCATELLI account is being used","Network connection is working normally","Browser has been refreshed or restarted","Issue reproduced in a clean browser context where appropriate","Exact error message or behaviour has been captured"]}]},{"heading":"Do not weaken security","blocks":[{"type":"callout","label":"Important","text":"Troubleshooting must never involve sharing passwords, bypassing access controls or exposing production secrets. Access should be restored through the approved authentication path."},{"type":"paragraph","text":"If the problem appears permission-related, record which area the user expected to access rather than attempting to reveal restricted content through another account."}]},{"heading":"Escalation note","blocks":[{"type":"procedure","steps":[{"title":"Describe the failure","text":"State the route or action, expected result and actual result."},{"title":"Attach useful evidence","text":"Include the exact error text and a screenshot only when it does not expose sensitive data."},{"title":"List checks already performed","text":"Prevent the next person from repeating basic troubleshooting unnecessarily."}]}]}],"related":["internal-communication-standards","file-organisation-and-naming"],"mainHubLinks":[]}'::jsonb,true,'2026-08-13') on conflict (id) do update set slug=excluded.slug,content_type=excluded.content_type,category_slug=excluded.category_slug,title=excluded.title,summary=excluded.summary,topic=excluded.topic,status=excluded.status,version=excluded.version,audience=excluded.audience,permissions=excluded.permissions,keywords=excluded.keywords,reading_minutes=excluded.reading_minutes,metadata=excluded.metadata,document=excluded.document,is_demo=excluded.is_demo,published_at=excluded.published_at,updated_at=now();
insert into public.atlas_content (id,slug,content_type,category_slug,title,summary,topic,status,version,audience,permissions,keywords,reading_minutes,metadata,document,is_demo,published_at) values ('playbook.responding-to-a-delayed-supplier','responding-to-a-delayed-supplier','playbook','suppliers','A supplier has stopped responding','A calm sequence for re-establishing contact, protecting the schedule and escalating only when silence becomes operationally material.','Supplier communication','current','0.1-demo','["All internal users"]'::jsonb,'["internal"]'::jsonb,'["supplier","vendor","delayed","no response","follow-up","deadline","communication"]'::jsonb,4,'{"id":"playbook.responding-to-a-delayed-supplier","slug":"responding-to-a-delayed-supplier","type":"playbook","category":"suppliers","topic":"Supplier communication","eyebrow":"Operational playbook","title":"A supplier has stopped responding","summary":"A calm sequence for re-establishing contact, protecting the schedule and escalating only when silence becomes operationally material.","keywords":["supplier","vendor","delayed","no response","follow-up","deadline","communication"],"owner":"Operations","readingMinutes":4,"approver":"Founder","version":"0.1-demo","publishedDate":"2026-08-13","lastReviewed":"2026-08-13","nextReview":"2026-10-13","languageStatus":"English demonstration","status":"current","audience":["All internal users"],"permissions":["internal"],"demo":true}'::jsonb,'{"id":"playbook.responding-to-a-delayed-supplier","slug":"responding-to-a-delayed-supplier","type":"playbook","category":"suppliers","topic":"Supplier communication","eyebrow":"Operational playbook","title":"A supplier has stopped responding","summary":"A calm sequence for re-establishing contact, protecting the schedule and escalating only when silence becomes operationally material.","keywords":["supplier","vendor","delayed","no response","follow-up","deadline","communication"],"owner":"Operations","readingMinutes":4,"approver":"Founder","version":"0.1-demo","publishedDate":"2026-08-13","lastReviewed":"2026-08-13","nextReview":"2026-10-13","languageStatus":"English demonstration","status":"current","audience":["All internal users"],"permissions":["internal"],"demo":true,"contentNotice":"Demonstration playbook for interface validation. It is not final MOSCATELLI policy and must be reviewed before operational use.","scenario":"Use this when a supplier has missed an expected reply or agreed update and the silence could begin to affect a sample, quotation, production milestone or decision.","immediateAction":["Verify the last agreed response date and the most recent complete message thread.","Send one concise follow-up that states the pending question, the original expectation and the next decision date.","Record the follow-up in the relevant project record and set a specific next-check time rather than repeatedly chasing."],"whoToInform":[{"role":"Project owner","when":"When the missed reply affects a committed internal milestone."},{"role":"Founder","when":"When production, cash commitment or launch timing may be affected."}],"whatToRecord":["Supplier name and contact used","Last substantive reply date","What information remains outstanding","Follow-up date/time and channel","Decision or milestone that may be affected"],"escalationConditions":["A second agreed response point passes without acknowledgement.","The supplier becomes unreachable across the established business channels.","The delay threatens a payment, production slot, launch date or material commitment."],"templatesResources":[{"kind":"Message structure","label":"Concise supplier follow-up","text":"Reference the pending item, restate the agreed timing, ask for a clear update, and state the date by which MOSCATELLI needs a response."},{"kind":"Record","label":"Project decision record","text":"Capture the impact and next decision point in the relevant MainHub record once integration is active."}],"relatedProcedures":["reviewing-a-supplier-quotation","supplier-sample-review-procedure"]}'::jsonb,true,'2026-08-13') on conflict (id) do update set slug=excluded.slug,content_type=excluded.content_type,category_slug=excluded.category_slug,title=excluded.title,summary=excluded.summary,topic=excluded.topic,status=excluded.status,version=excluded.version,audience=excluded.audience,permissions=excluded.permissions,keywords=excluded.keywords,reading_minutes=excluded.reading_minutes,metadata=excluded.metadata,document=excluded.document,is_demo=excluded.is_demo,published_at=excluded.published_at,updated_at=now();
insert into public.atlas_content (id,slug,content_type,category_slug,title,summary,topic,status,version,audience,permissions,keywords,reading_minutes,metadata,document,is_demo,published_at) values ('playbook.sample-arrived-damaged','sample-arrived-damaged','playbook','products-and-quality','A sample arrived damaged','A preservation-first response for documenting damage, separating transit issues from workmanship issues and protecting the review trail.','Sample stages','current','0.1-demo','["All internal users"]'::jsonb,'["internal"]'::jsonb,'["sample","prototype","damaged","quality","shipping","evidence","photography"]'::jsonb,4,'{"id":"playbook.sample-arrived-damaged","slug":"sample-arrived-damaged","type":"playbook","category":"products-and-quality","topic":"Sample stages","eyebrow":"Operational playbook","title":"A sample arrived damaged","summary":"A preservation-first response for documenting damage, separating transit issues from workmanship issues and protecting the review trail.","keywords":["sample","prototype","damaged","quality","shipping","evidence","photography"],"owner":"Product Development","readingMinutes":4,"approver":"Founder","version":"0.1-demo","publishedDate":"2026-08-13","lastReviewed":"2026-08-13","nextReview":"2026-10-13","languageStatus":"English demonstration","status":"current","audience":["All internal users"],"permissions":["internal"],"demo":true}'::jsonb,'{"id":"playbook.sample-arrived-damaged","slug":"sample-arrived-damaged","type":"playbook","category":"products-and-quality","topic":"Sample stages","eyebrow":"Operational playbook","title":"A sample arrived damaged","summary":"A preservation-first response for documenting damage, separating transit issues from workmanship issues and protecting the review trail.","keywords":["sample","prototype","damaged","quality","shipping","evidence","photography"],"owner":"Product Development","readingMinutes":4,"approver":"Founder","version":"0.1-demo","publishedDate":"2026-08-13","lastReviewed":"2026-08-13","nextReview":"2026-10-13","languageStatus":"English demonstration","status":"current","audience":["All internal users"],"permissions":["internal"],"demo":true,"contentNotice":"Demonstration playbook for interface validation. It is not final MOSCATELLI policy and must be reviewed before operational use.","scenario":"Use this when a physical sample arrives with visible damage, deformation, contamination, missing components or packaging failure that could distort the product review.","immediateAction":["Do not repair, clean or alter the sample before documenting its received condition.","Photograph the outer packaging, labels, internal protection and damage in a consistent sequence.","Separate what appears to be transit damage from any possible construction or quality issue; do not assume the cause."],"whoToInform":[{"role":"Product owner","when":"Immediately after the received condition is documented."},{"role":"Supplier contact","when":"After evidence is complete and the issue can be described neutrally."}],"whatToRecord":["Delivery date and carrier reference","Packaging condition","Photo set location","Observed damage without speculation","Whether review can continue or needs replacement"],"escalationConditions":["The damage prevents meaningful fit, construction or material review.","There is repeated damage across more than one shipment or sample.","A quality dispute begins or replacement timing affects a launch milestone."],"templatesResources":[{"kind":"Checklist","label":"Damage evidence sequence","text":"Outer package → shipping label → internal protection → full sample → close-up damage → scale/reference image."},{"kind":"Reference","label":"Photography approval checklist","route":"#/article/photography-approval-checklist"}],"relatedProcedures":["supplier-sample-review-procedure","photography-approval-checklist"]}'::jsonb,true,'2026-08-13') on conflict (id) do update set slug=excluded.slug,content_type=excluded.content_type,category_slug=excluded.category_slug,title=excluded.title,summary=excluded.summary,topic=excluded.topic,status=excluded.status,version=excluded.version,audience=excluded.audience,permissions=excluded.permissions,keywords=excluded.keywords,reading_minutes=excluded.reading_minutes,metadata=excluded.metadata,document=excluded.document,is_demo=excluded.is_demo,published_at=excluded.published_at,updated_at=now();
insert into public.atlas_content (id,slug,content_type,category_slug,title,summary,topic,status,version,audience,permissions,keywords,reading_minutes,metadata,document,is_demo,published_at) values ('playbook.invoice-does-not-match-quotation','invoice-does-not-match-quotation','playbook','finance-and-administration','An invoice does not match the quotation','A verification sequence for mismatched amounts, quantities, currencies or payment terms before any financial record is treated as final.','Invoices','current','0.1-demo','["All internal users"]'::jsonb,'["internal"]'::jsonb,'["invoice","bill","quotation","quote","amount","currency","payment","mismatch"]'::jsonb,4,'{"id":"playbook.invoice-does-not-match-quotation","slug":"invoice-does-not-match-quotation","type":"playbook","category":"finance-and-administration","topic":"Invoices","eyebrow":"Operational playbook","title":"An invoice does not match the quotation","summary":"A verification sequence for mismatched amounts, quantities, currencies or payment terms before any financial record is treated as final.","keywords":["invoice","bill","quotation","quote","amount","currency","payment","mismatch"],"owner":"Finance & Administration","readingMinutes":4,"approver":"Founder","version":"0.1-demo","publishedDate":"2026-08-13","lastReviewed":"2026-08-13","nextReview":"2026-10-13","languageStatus":"English demonstration","status":"current","audience":["All internal users"],"permissions":["internal"],"demo":true}'::jsonb,'{"id":"playbook.invoice-does-not-match-quotation","slug":"invoice-does-not-match-quotation","type":"playbook","category":"finance-and-administration","topic":"Invoices","eyebrow":"Operational playbook","title":"An invoice does not match the quotation","summary":"A verification sequence for mismatched amounts, quantities, currencies or payment terms before any financial record is treated as final.","keywords":["invoice","bill","quotation","quote","amount","currency","payment","mismatch"],"owner":"Finance & Administration","readingMinutes":4,"approver":"Founder","version":"0.1-demo","publishedDate":"2026-08-13","lastReviewed":"2026-08-13","nextReview":"2026-10-13","languageStatus":"English demonstration","status":"current","audience":["All internal users"],"permissions":["internal"],"demo":true,"contentNotice":"Demonstration playbook for interface validation. It is not final MOSCATELLI policy and must be reviewed before operational use.","scenario":"Use this when an invoice differs from the approved quotation, purchase understanding or documented commercial terms.","immediateAction":["Pause approval of the disputed amount; do not silently edit the supplier document or reinterpret the difference.","Compare the invoice against the latest approved quotation and any documented revision.","Identify each discrepancy explicitly: amount, quantity, currency, tax, freight, payment term or line item."],"whoToInform":[{"role":"Budget/record owner","when":"As soon as the mismatch is confirmed."},{"role":"Founder","when":"Before approving a material exception or new commercial term."}],"whatToRecord":["Invoice identifier and date","Quotation/version used for comparison","Exact mismatching line(s)","Currency and tax treatment shown","Supplier explanation and final resolution"],"escalationConditions":["The supplier requests payment before correcting or explaining the discrepancy.","The difference changes the approved budget or commitment.","The mismatch suggests duplicate billing, an undocumented scope change or a recurring documentation problem."],"templatesResources":[{"kind":"Comparison","label":"Discrepancy note","text":"List the quoted value, invoiced value, difference and source document for each mismatched line."},{"kind":"Reference","label":"Recording a training expense","route":"#/article/recording-a-training-expense"}],"relatedProcedures":["reviewing-a-supplier-quotation","recording-a-training-expense"]}'::jsonb,true,'2026-08-13') on conflict (id) do update set slug=excluded.slug,content_type=excluded.content_type,category_slug=excluded.category_slug,title=excluded.title,summary=excluded.summary,topic=excluded.topic,status=excluded.status,version=excluded.version,audience=excluded.audience,permissions=excluded.permissions,keywords=excluded.keywords,reading_minutes=excluded.reading_minutes,metadata=excluded.metadata,document=excluded.document,is_demo=excluded.is_demo,published_at=excluded.published_at,updated_at=now();
insert into public.atlas_content (id,slug,content_type,category_slug,title,summary,topic,status,version,audience,permissions,keywords,reading_minutes,metadata,document,is_demo,published_at) values ('playbook.deadline-will-be-missed','deadline-will-be-missed','playbook','operations','A deadline will be missed','A decision-first response for surfacing slippage early, separating facts from assumptions and resetting commitments with a documented owner.','Project procedures','current','0.1-demo','["All internal users"]'::jsonb,'["internal"]'::jsonb,'["deadline","late","delay","milestone","schedule","timeline","escalation"]'::jsonb,4,'{"id":"playbook.deadline-will-be-missed","slug":"deadline-will-be-missed","type":"playbook","category":"operations","topic":"Project procedures","eyebrow":"Operational playbook","title":"A deadline will be missed","summary":"A decision-first response for surfacing slippage early, separating facts from assumptions and resetting commitments with a documented owner.","keywords":["deadline","late","delay","milestone","schedule","timeline","escalation"],"owner":"Operations","readingMinutes":4,"approver":"Founder","version":"0.1-demo","publishedDate":"2026-08-13","lastReviewed":"2026-08-13","nextReview":"2026-10-13","languageStatus":"English demonstration","status":"current","audience":["All internal users"],"permissions":["internal"],"demo":true}'::jsonb,'{"id":"playbook.deadline-will-be-missed","slug":"deadline-will-be-missed","type":"playbook","category":"operations","topic":"Project procedures","eyebrow":"Operational playbook","title":"A deadline will be missed","summary":"A decision-first response for surfacing slippage early, separating facts from assumptions and resetting commitments with a documented owner.","keywords":["deadline","late","delay","milestone","schedule","timeline","escalation"],"owner":"Operations","readingMinutes":4,"approver":"Founder","version":"0.1-demo","publishedDate":"2026-08-13","lastReviewed":"2026-08-13","nextReview":"2026-10-13","languageStatus":"English demonstration","status":"current","audience":["All internal users"],"permissions":["internal"],"demo":true,"contentNotice":"Demonstration playbook for interface validation. It is not final MOSCATELLI policy and must be reviewed before operational use.","scenario":"Use this when a committed internal or external milestone is no longer realistically achievable on the agreed date.","immediateAction":["Confirm the earliest credible completion date and the specific dependency causing the change.","Notify the owner before the deadline passes; avoid waiting for perfect information.","Present the impact, the proposed revised date and one practical mitigation option."],"whoToInform":[{"role":"Project owner","when":"As soon as slippage is credible rather than merely possible."},{"role":"Founder","when":"When launch, supplier commitments, public communication or material spend may change."}],"whatToRecord":["Original date and owner","Cause stated as observable fact","New forecast date","Affected dependencies","Decision made and person responsible"],"escalationConditions":["The revised date affects a launch, customer-facing commitment or production slot.","More than one dependent milestone moves.","The cause is recurring or reveals a process/control failure."],"templatesResources":[{"kind":"Update structure","label":"Deadline change note","text":"Original commitment → current fact → impact → revised date → mitigation → decision needed."}],"relatedProcedures":["how-moscatelli-records-decisions","file-organisation-and-naming"]}'::jsonb,true,'2026-08-13') on conflict (id) do update set slug=excluded.slug,content_type=excluded.content_type,category_slug=excluded.category_slug,title=excluded.title,summary=excluded.summary,topic=excluded.topic,status=excluded.status,version=excluded.version,audience=excluded.audience,permissions=excluded.permissions,keywords=excluded.keywords,reading_minutes=excluded.reading_minutes,metadata=excluded.metadata,document=excluded.document,is_demo=excluded.is_demo,published_at=excluded.published_at,updated_at=now();
insert into public.atlas_content (id,slug,content_type,category_slug,title,summary,topic,status,version,audience,permissions,keywords,reading_minutes,metadata,document,is_demo,published_at) values ('playbook.confidential-information-request','confidential-information-request','playbook','people','Someone requests confidential information','A low-drama response for pausing disclosure, verifying need and authority, and recording sensitive-information decisions.','Internal policies','current','0.1-demo','["All internal users"]'::jsonb,'["internal"]'::jsonb,'["confidential","private","information","data","supplier","request","permission"]'::jsonb,4,'{"id":"playbook.confidential-information-request","slug":"confidential-information-request","type":"playbook","category":"people","topic":"Internal policies","eyebrow":"Operational playbook","title":"Someone requests confidential information","summary":"A low-drama response for pausing disclosure, verifying need and authority, and recording sensitive-information decisions.","keywords":["confidential","private","information","data","supplier","request","permission"],"owner":"Operations","readingMinutes":4,"approver":"Founder","version":"0.1-demo","publishedDate":"2026-08-13","lastReviewed":"2026-08-13","nextReview":"2026-10-13","languageStatus":"English demonstration","status":"current","audience":["All internal users"],"permissions":["internal"],"demo":true}'::jsonb,'{"id":"playbook.confidential-information-request","slug":"confidential-information-request","type":"playbook","category":"people","topic":"Internal policies","eyebrow":"Operational playbook","title":"Someone requests confidential information","summary":"A low-drama response for pausing disclosure, verifying need and authority, and recording sensitive-information decisions.","keywords":["confidential","private","information","data","supplier","request","permission"],"owner":"Operations","readingMinutes":4,"approver":"Founder","version":"0.1-demo","publishedDate":"2026-08-13","lastReviewed":"2026-08-13","nextReview":"2026-10-13","languageStatus":"English demonstration","status":"current","audience":["All internal users"],"permissions":["internal"],"demo":true,"contentNotice":"Demonstration playbook for interface validation. It is not final MOSCATELLI policy and must be reviewed before operational use.","scenario":"Use this when a supplier, contractor, candidate, team member or external party asks for information that may be commercially sensitive, personal, restricted or outside their usual access.","immediateAction":["Do not disclose the information while authority or purpose is unclear.","Clarify exactly what is being requested, why it is needed and who will receive it.","Route the request to the information owner or Founder when the permission basis is not already established."],"whoToInform":[{"role":"Information owner","when":"Before any restricted information is shared."},{"role":"Founder","when":"For commercially sensitive, strategic, financial or exceptional disclosures."}],"whatToRecord":["Requester and organisation","Exact information requested","Stated purpose","Decision owner and approval/decline","What was ultimately shared, if anything"],"escalationConditions":["The requester pressures for immediate disclosure without a clear need.","The request includes financial, strategic, personal or access-control information.","There is doubt about recipient identity, forwarding risk or contractual confidentiality."],"templatesResources":[{"kind":"Response structure","label":"Holding reply","text":"Acknowledge the request, explain that access must be verified internally, and give a realistic time for a response without implying approval."}],"relatedProcedures":["internal-communication-standards","working-with-standards-at-moscatelli"]}'::jsonb,true,'2026-08-13') on conflict (id) do update set slug=excluded.slug,content_type=excluded.content_type,category_slug=excluded.category_slug,title=excluded.title,summary=excluded.summary,topic=excluded.topic,status=excluded.status,version=excluded.version,audience=excluded.audience,permissions=excluded.permissions,keywords=excluded.keywords,reading_minutes=excluded.reading_minutes,metadata=excluded.metadata,document=excluded.document,is_demo=excluded.is_demo,published_at=excluded.published_at,updated_at=now();
insert into public.atlas_content (id,slug,content_type,category_slug,title,summary,topic,status,version,audience,permissions,keywords,reading_minutes,metadata,document,is_demo,published_at) values ('playbook.mainhub-access-failure','mainhub-access-failure','playbook','systems','A team member cannot access MainHub','A short diagnostic route for distinguishing account, session and permission problems before escalating a systems issue.','MainHub','current','0.1-demo','["All internal users"]'::jsonb,'["internal"]'::jsonb,'["MainHub","login","sign in","access","account","permission","troubleshooting"]'::jsonb,4,'{"id":"playbook.mainhub-access-failure","slug":"mainhub-access-failure","type":"playbook","category":"systems","topic":"MainHub","eyebrow":"Operational playbook","title":"A team member cannot access MainHub","summary":"A short diagnostic route for distinguishing account, session and permission problems before escalating a systems issue.","keywords":["MainHub","login","sign in","access","account","permission","troubleshooting"],"owner":"Operations","readingMinutes":4,"approver":"Founder","version":"0.1-demo","publishedDate":"2026-08-13","lastReviewed":"2026-08-13","nextReview":"2026-10-13","languageStatus":"English demonstration","status":"current","audience":["All internal users"],"permissions":["internal"],"demo":true}'::jsonb,'{"id":"playbook.mainhub-access-failure","slug":"mainhub-access-failure","type":"playbook","category":"systems","topic":"MainHub","eyebrow":"Operational playbook","title":"A team member cannot access MainHub","summary":"A short diagnostic route for distinguishing account, session and permission problems before escalating a systems issue.","keywords":["MainHub","login","sign in","access","account","permission","troubleshooting"],"owner":"Operations","readingMinutes":4,"approver":"Founder","version":"0.1-demo","publishedDate":"2026-08-13","lastReviewed":"2026-08-13","nextReview":"2026-10-13","languageStatus":"English demonstration","status":"current","audience":["All internal users"],"permissions":["internal"],"demo":true,"contentNotice":"Demonstration playbook for interface validation. It is not final MOSCATELLI policy and must be reviewed before operational use.","scenario":"Use this when an internal user cannot sign in to MainHub, can sign in but cannot reach an expected area, or sees an access state that differs from their role.","immediateAction":["Confirm whether the failure is sign-in, session, device/browser or permission-specific.","Ask the user to capture the exact visible error/state without sharing passwords or authentication codes.","Check whether the issue occurs in a clean session or another supported browser before treating it as a permissions change."],"whoToInform":[{"role":"Operations / system owner","when":"After the basic state is identified."},{"role":"Founder","when":"A role/permission change is actually required or sensitive access is involved."}],"whatToRecord":["User identity/account email","Device/browser and approximate time","Exact route or function attempted","Visible error text or screenshot location","Whether sign-in itself succeeds"],"escalationConditions":["Multiple users are affected.","The user appears to have access they should not have.","A required role/permission mapping is missing or unexpectedly changed."],"templatesResources":[{"kind":"Reference","label":"MainHub access troubleshooting","route":"#/article/mainhub-access-troubleshooting"}],"relatedProcedures":["mainhub-access-troubleshooting"]}'::jsonb,true,'2026-08-13') on conflict (id) do update set slug=excluded.slug,content_type=excluded.content_type,category_slug=excluded.category_slug,title=excluded.title,summary=excluded.summary,topic=excluded.topic,status=excluded.status,version=excluded.version,audience=excluded.audience,permissions=excluded.permissions,keywords=excluded.keywords,reading_minutes=excluded.reading_minutes,metadata=excluded.metadata,document=excluded.document,is_demo=excluded.is_demo,published_at=excluded.published_at,updated_at=now();
insert into public.atlas_content (id,slug,content_type,category_slug,title,summary,topic,status,version,audience,permissions,keywords,reading_minutes,metadata,document,is_demo,published_at) values ('playbook.image-has-wrong-resolution','image-has-wrong-resolution','playbook','brand','An image has the wrong resolution','A controlled response for stopping unsuitable imagery from progressing while preserving the source file and approval history.','Photography','current','0.1-demo','["All internal users"]'::jsonb,'["internal"]'::jsonb,'["image","resolution","photography","pixels","quality","approval","asset"]'::jsonb,4,'{"id":"playbook.image-has-wrong-resolution","slug":"image-has-wrong-resolution","type":"playbook","category":"brand","topic":"Photography","eyebrow":"Operational playbook","title":"An image has the wrong resolution","summary":"A controlled response for stopping unsuitable imagery from progressing while preserving the source file and approval history.","keywords":["image","resolution","photography","pixels","quality","approval","asset"],"owner":"Creative Direction","readingMinutes":4,"approver":"Founder","version":"0.1-demo","publishedDate":"2026-08-13","lastReviewed":"2026-08-13","nextReview":"2026-10-13","languageStatus":"English demonstration","status":"current","audience":["All internal users"],"permissions":["internal"],"demo":true}'::jsonb,'{"id":"playbook.image-has-wrong-resolution","slug":"image-has-wrong-resolution","type":"playbook","category":"brand","topic":"Photography","eyebrow":"Operational playbook","title":"An image has the wrong resolution","summary":"A controlled response for stopping unsuitable imagery from progressing while preserving the source file and approval history.","keywords":["image","resolution","photography","pixels","quality","approval","asset"],"owner":"Creative Direction","readingMinutes":4,"approver":"Founder","version":"0.1-demo","publishedDate":"2026-08-13","lastReviewed":"2026-08-13","nextReview":"2026-10-13","languageStatus":"English demonstration","status":"current","audience":["All internal users"],"permissions":["internal"],"demo":true,"contentNotice":"Demonstration playbook for interface validation. It is not final MOSCATELLI policy and must be reviewed before operational use.","scenario":"Use this when an image is too small, incorrectly exported, visibly degraded or otherwise unsuitable for its intended MOSCATELLI output.","immediateAction":["Do not upscale or overwrite the source file merely to make the dimensions appear compliant.","Identify the intended output and the actual pixel dimensions/file characteristics.","Locate the highest-quality source or request a new export before approval continues."],"whoToInform":[{"role":"Creative Direction","when":"When the asset cannot meet the intended output without source replacement."},{"role":"Asset owner","when":"When a new export or original file is required."}],"whatToRecord":["Asset filename and location","Intended use/output","Actual dimensions and file format","Source/original availability","Replacement or approval decision"],"escalationConditions":["No suitable source exists.","The image has already been distributed or published in the wrong form.","Repeated export errors indicate an asset-management workflow problem."],"templatesResources":[{"kind":"Reference","label":"Photography approval checklist","route":"#/article/photography-approval-checklist"},{"kind":"Reference","label":"File organisation and naming","route":"#/article/file-organisation-and-naming"}],"relatedProcedures":["photography-approval-checklist","file-organisation-and-naming"]}'::jsonb,true,'2026-08-13') on conflict (id) do update set slug=excluded.slug,content_type=excluded.content_type,category_slug=excluded.category_slug,title=excluded.title,summary=excluded.summary,topic=excluded.topic,status=excluded.status,version=excluded.version,audience=excluded.audience,permissions=excluded.permissions,keywords=excluded.keywords,reading_minutes=excluded.reading_minutes,metadata=excluded.metadata,document=excluded.document,is_demo=excluded.is_demo,published_at=excluded.published_at,updated_at=now();
insert into public.atlas_content (id,slug,content_type,category_slug,title,summary,topic,status,version,audience,permissions,keywords,reading_minutes,metadata,document,is_demo,published_at) values ('playbook.payment-recorded-twice','payment-recorded-twice','playbook','finance-and-administration','A payment was recorded twice','A non-destructive verification process for suspected duplicate records before correcting financial history.','Payments','current','0.1-demo','["All internal users"]'::jsonb,'["internal"]'::jsonb,'["payment","duplicate","record","expense","finance","transaction","twice"]'::jsonb,4,'{"id":"playbook.payment-recorded-twice","slug":"payment-recorded-twice","type":"playbook","category":"finance-and-administration","topic":"Payments","eyebrow":"Operational playbook","title":"A payment was recorded twice","summary":"A non-destructive verification process for suspected duplicate records before correcting financial history.","keywords":["payment","duplicate","record","expense","finance","transaction","twice"],"owner":"Finance & Administration","readingMinutes":4,"approver":"Founder","version":"0.1-demo","publishedDate":"2026-08-13","lastReviewed":"2026-08-13","nextReview":"2026-10-13","languageStatus":"English demonstration","status":"current","audience":["All internal users"],"permissions":["internal"],"demo":true}'::jsonb,'{"id":"playbook.payment-recorded-twice","slug":"payment-recorded-twice","type":"playbook","category":"finance-and-administration","topic":"Payments","eyebrow":"Operational playbook","title":"A payment was recorded twice","summary":"A non-destructive verification process for suspected duplicate records before correcting financial history.","keywords":["payment","duplicate","record","expense","finance","transaction","twice"],"owner":"Finance & Administration","readingMinutes":4,"approver":"Founder","version":"0.1-demo","publishedDate":"2026-08-13","lastReviewed":"2026-08-13","nextReview":"2026-10-13","languageStatus":"English demonstration","status":"current","audience":["All internal users"],"permissions":["internal"],"demo":true,"contentNotice":"Demonstration playbook for interface validation. It is not final MOSCATELLI policy and must be reviewed before operational use.","scenario":"Use this when two records appear to represent the same payment, expense or supplier transaction.","immediateAction":["Do not delete either record until the duplication is verified against the underlying transaction evidence.","Compare amount, currency, date, supplier/reference and supporting receipt or invoice.","Mark the suspected duplicate for review using the available non-destructive workflow; preserve the audit trail."],"whoToInform":[{"role":"Finance record owner","when":"Once the suspected duplicate is identified."},{"role":"Founder","when":"The correction changes reporting, a supplier balance or an approved commitment."}],"whatToRecord":["Both record identifiers","Underlying bank/payment reference","Amount and currency","Evidence used to determine duplication","Correction taken and who approved it"],"escalationConditions":["The underlying transaction itself may have been paid twice.","The records differ in a way that cannot be reconciled from evidence.","Removing/correcting the duplicate would materially change a reported total."],"templatesResources":[{"kind":"Reference","label":"Recording a training expense","route":"#/article/recording-a-training-expense"}],"relatedProcedures":["recording-a-training-expense","how-moscatelli-records-decisions"]}'::jsonb,true,'2026-08-13') on conflict (id) do update set slug=excluded.slug,content_type=excluded.content_type,category_slug=excluded.category_slug,title=excluded.title,summary=excluded.summary,topic=excluded.topic,status=excluded.status,version=excluded.version,audience=excluded.audience,permissions=excluded.permissions,keywords=excluded.keywords,reading_minutes=excluded.reading_minutes,metadata=excluded.metadata,document=excluded.document,is_demo=excluded.is_d