insert into public.atlas_content (id,slug,content_type,category_slug,title,summary,topic,status,version,audience,permissions,keywords,reading_minutes,metadata,document,is_demo,published_at) values ('playbook.shipment-held-at-customs','shipment-held-at-customs','playbook','operations','A shipment is held at customs','A fact-led response for establishing the hold reason, gathering documents and escalating only with the relevant shipment record intact.','Customs','current','0.1-demo','["All internal users"]'::jsonb,'["internal"]'::jsonb,'["shipment","shipping","delivery","customs","held","carrier","documents"]'::jsonb,4,'{"id":"playbook.shipment-held-at-customs","slug":"shipment-held-at-customs","type":"playbook","category":"operations","topic":"Customs","eyebrow":"Operational playbook","title":"A shipment is held at customs","summary":"A fact-led response for establishing the hold reason, gathering documents and escalating only with the relevant shipment record intact.","keywords":["shipment","shipping","delivery","customs","held","carrier","documents"],"owner":"Operations","readingMinutes":4,"approver":"Founder","version":"0.1-demo","publishedDate":"2026-08-13","lastReviewed":"2026-08-13","nextReview":"2026-10-13","languageStatus":"English demonstration","status":"current","audience":["All internal users"],"permissions":["internal"],"demo":true}'::jsonb,'{"id":"playbook.shipment-held-at-customs","slug":"shipment-held-at-customs","type":"playbook","category":"operations","topic":"Customs","eyebrow":"Operational playbook","title":"A shipment is held at customs","summary":"A fact-led response for establishing the hold reason, gathering documents and escalating only with the relevant shipment record intact.","keywords":["shipment","shipping","delivery","customs","held","carrier","documents"],"owner":"Operations","readingMinutes":4,"approver":"Founder","version":"0.1-demo","publishedDate":"2026-08-13","lastReviewed":"2026-08-13","nextReview":"2026-10-13","languageStatus":"English demonstration","status":"current","audience":["All internal users"],"permissions":["internal"],"demo":true,"contentNotice":"Demonstration playbook for interface validation. It is not final MOSCATELLI policy and must be reviewed before operational use.","scenario":"Use this when a carrier, broker or customs authority indicates that a shipment is being held, delayed for documentation or awaiting clarification.","immediateAction":["Confirm the shipment reference, current carrier status and stated reason for the hold.","Gather the commercial invoice, packing information and any already-issued shipment documentation without creating replacement documents casually.","Identify who is formally requesting information and respond through the established carrier/broker channel."],"whoToInform":[{"role":"Shipment/project owner","when":"Immediately once a hold is confirmed."},{"role":"Founder","when":"The hold threatens a launch/production milestone or requires an exceptional financial/commercial decision."}],"whatToRecord":["Tracking/shipment reference","Carrier/broker contact","Stated hold reason","Documents requested/provided","Deadlines, fees or milestone impact communicated"],"escalationConditions":["The reason for hold is unclear or contradictory.","Additional charges, return/destruction risk or legal/compliance questions arise.","The delivery delay affects a critical sample, production or launch milestone."],"templatesResources":[{"kind":"Record","label":"Shipment incident note","text":"Keep the carrier status, request, documents sent, timestamps and next expected update in one continuous record."}],"relatedProcedures":["file-organisation-and-naming","how-moscatelli-records-decisions"]}'::jsonb,true,'2026-08-13') on conflict (id) do update set slug=excluded.slug,content_type=excluded.content_type,category_slug=excluded.category_slug,title=excluded.title,summary=excluded.summary,topic=excluded.topic,status=excluded.status,version=excluded.version,audience=excluded.audience,permissions=excluded.permissions,keywords=excluded.keywords,reading_minutes=excluded.reading_minutes,metadata=excluded.metadata,document=excluded.document,is_demo=excluded.is_demo,published_at=excluded.published_at,updated_at=now();
insert into public.atlas_content (id,slug,content_type,category_slug,title,summary,topic,status,version,audience,permissions,keywords,reading_minutes,metadata,document,is_demo,published_at) values ('lesson.welcome-to-atlas','welcome-to-atlas','academia-lesson','systems','Welcome to Atlas','Understand what Atlas is for, what it is not, and when to consult it before asking for institutional guidance.','Atlas','current','0.1-demo','["Internal learners"]'::jsonb,'["internal"]'::jsonb,'["Atlas","onboarding","knowledge","institutional memory","MainHub"]'::jsonb,12,'{"id":"lesson.welcome-to-atlas","slug":"welcome-to-atlas","type":"academia-lesson","courseSlug":"moscatelli-onboarding","moduleId":"orientation","order":1,"category":"systems","topic":"Atlas","eyebrow":"Academia lesson","title":"Welcome to Atlas","summary":"Understand what Atlas is for, what it is not, and when to consult it before asking for institutional guidance.","keywords":["Atlas","onboarding","knowledge","institutional memory","MainHub"],"estimatedMinutes":12,"readingMinutes":12,"requirement":"required","acknowledgementRequired":true,"owner":"Academia","approver":"Founder","version":"0.1-demo","publishedDate":"2026-08-13","lastReviewed":"2026-08-13","nextReview":"2026-10-13","languageStatus":"English demonstration","status":"current","audience":["Internal learners"],"permissions":["internal"],"demo":true}'::jsonb,'{"id":"lesson.welcome-to-atlas","slug":"welcome-to-atlas","type":"academia-lesson","courseSlug":"moscatelli-onboarding","moduleId":"orientation","order":1,"category":"systems","topic":"Atlas","eyebrow":"Academia lesson","title":"Welcome to Atlas","summary":"Understand what Atlas is for, what it is not, and when to consult it before asking for institutional guidance.","keywords":["Atlas","onboarding","knowledge","institutional memory","MainHub"],"estimatedMinutes":12,"readingMinutes":12,"requirement":"required","acknowledgementRequired":true,"owner":"Academia","approver":"Founder","version":"0.1-demo","publishedDate":"2026-08-13","lastReviewed":"2026-08-13","nextReview":"2026-10-13","languageStatus":"English demonstration","status":"current","audience":["Internal learners"],"permissions":["internal"],"demo":true,"contentNotice":"Demonstration learning content for interface validation. It is not final MOSCATELLI policy, curriculum or language instruction and must be reviewed before operational use.","sections":[{"heading":"The purpose of Atlas","blocks":[{"type":"paragraph","text":"Atlas is the internal reference layer for MOSCATELLI. It explains standards, procedures, learning material and recurring situations; MainHub remains the place where live work is carried out and recorded."},{"type":"callout","label":"Development note","text":"The content in this preview validates the learning interface only and is not final policy."}]},{"heading":"A simple working rule","blocks":[{"type":"list","items":["Use Atlas when you need to understand how something should be approached.","Use MainHub when you need to act on live company work or record a current decision.","When a reference and a live record conflict, stop and raise the discrepancy rather than silently choosing one."]}]}]}'::jsonb,true,'2026-08-13') on conflict (id) do update set slug=excluded.slug,content_type=excluded.content_type,category_slug=excluded.category_slug,title=excluded.title,summary=excluded.summary,topic=excluded.topic,status=excluded.status,version=excluded.version,audience=excluded.audience,permissions=excluded.permissions,keywords=excluded.keywords,reading_minutes=excluded.reading_minutes,metadata=excluded.metadata,document=excluded.document,is_demo=excluded.is_demo,published_at=excluded.published_at,updated_at=now();
insert into public.atlas_content (id,slug,content_type,category_slug,title,summary,topic,status,version,audience,permissions,keywords,reading_minutes,metadata,document,is_demo,published_at) values ('lesson.working-with-standards','working-with-standards','academia-lesson','the-house','Working with standards','Learn how to treat published standards as controlled references rather than informal suggestions.','Mission and values','current','0.1-demo','["Internal learners"]'::jsonb,'["internal"]'::jsonb,'["standards","procedure","version","review","governance"]'::jsonb,16,'{"id":"lesson.working-with-standards","slug":"working-with-standards","type":"academia-lesson","courseSlug":"moscatelli-onboarding","moduleId":"orientation","order":2,"category":"the-house","topic":"Mission and values","eyebrow":"Academia lesson","title":"Working with standards","summary":"Learn how to treat published standards as controlled references rather than informal suggestions.","keywords":["standards","procedure","version","review","governance"],"estimatedMinutes":16,"readingMinutes":16,"requirement":"required","acknowledgementRequired":false,"owner":"Academia","approver":"Founder","version":"0.1-demo","publishedDate":"2026-08-13","lastReviewed":"2026-08-13","nextReview":"2026-10-13","languageStatus":"English demonstration","status":"current","audience":["Internal learners"],"permissions":["internal"],"demo":true}'::jsonb,'{"id":"lesson.working-with-standards","slug":"working-with-standards","type":"academia-lesson","courseSlug":"moscatelli-onboarding","moduleId":"orientation","order":2,"category":"the-house","topic":"Mission and values","eyebrow":"Academia lesson","title":"Working with standards","summary":"Learn how to treat published standards as controlled references rather than informal suggestions.","keywords":["standards","procedure","version","review","governance"],"estimatedMinutes":16,"readingMinutes":16,"requirement":"required","acknowledgementRequired":false,"owner":"Academia","approver":"Founder","version":"0.1-demo","publishedDate":"2026-08-13","lastReviewed":"2026-08-13","nextReview":"2026-10-13","languageStatus":"English demonstration","status":"current","audience":["Internal learners"],"permissions":["internal"],"demo":true,"contentNotice":"Demonstration learning content for interface validation. It is not final MOSCATELLI policy, curriculum or language instruction and must be reviewed before operational use.","sections":[{"heading":"Read the record, not only the headline","blocks":[{"type":"paragraph","text":"A standard should be read together with its owner, version, status and review information. Those details establish whether the reference is current and who is responsible for it."}]},{"heading":"When something is unclear","blocks":[{"type":"procedure","steps":[{"title":"Check the current version","text":"Confirm that the item is current rather than archived or under review."},{"title":"Identify the owner","text":"Direct clarification to the person or function responsible for the standard."},{"title":"Preserve the uncertainty","text":"Do not turn an interpretation into a new rule without a documented decision."}]}]}]}'::jsonb,true,'2026-08-13') on conflict (id) do update set slug=excluded.slug,content_type=excluded.content_type,category_slug=excluded.category_slug,title=excluded.title,summary=excluded.summary,topic=excluded.topic,status=excluded.status,version=excluded.version,audience=excluded.audience,permissions=excluded.permissions,keywords=excluded.keywords,reading_minutes=excluded.reading_minutes,metadata=excluded.metadata,document=excluded.document,is_demo=excluded.is_demo,published_at=excluded.published_at,updated_at=now();
insert into public.atlas_content (id,slug,content_type,category_slug,title,summary,topic,status,version,audience,permissions,keywords,reading_minutes,metadata,document,is_demo,published_at) values ('lesson.recording-decisions','recording-decisions','academia-lesson','operations','Recording decisions','Practice a concise decision record that preserves context without turning routine work into bureaucracy.','Records','current','0.1-demo','["Internal learners"]'::jsonb,'["internal"]'::jsonb,'["record","decision","owner","context","MainHub"]'::jsonb,20,'{"id":"lesson.recording-decisions","slug":"recording-decisions","type":"academia-lesson","courseSlug":"moscatelli-onboarding","moduleId":"working-practice","order":3,"category":"operations","topic":"Records","eyebrow":"Academia lesson","title":"Recording decisions","summary":"Practice a concise decision record that preserves context without turning routine work into bureaucracy.","keywords":["record","decision","owner","context","MainHub"],"estimatedMinutes":20,"readingMinutes":20,"requirement":"required","acknowledgementRequired":true,"owner":"Academia","approver":"Founder","version":"0.1-demo","publishedDate":"2026-08-13","lastReviewed":"2026-08-13","nextReview":"2026-10-13","languageStatus":"English demonstration","status":"current","audience":["Internal learners"],"permissions":["internal"],"demo":true}'::jsonb,'{"id":"lesson.recording-decisions","slug":"recording-decisions","type":"academia-lesson","courseSlug":"moscatelli-onboarding","moduleId":"working-practice","order":3,"category":"operations","topic":"Records","eyebrow":"Academia lesson","title":"Recording decisions","summary":"Practice a concise decision record that preserves context without turning routine work into bureaucracy.","keywords":["record","decision","owner","context","MainHub"],"estimatedMinutes":20,"readingMinutes":20,"requirement":"required","acknowledgementRequired":true,"owner":"Academia","approver":"Founder","version":"0.1-demo","publishedDate":"2026-08-13","lastReviewed":"2026-08-13","nextReview":"2026-10-13","languageStatus":"English demonstration","status":"current","audience":["Internal learners"],"permissions":["internal"],"demo":true,"contentNotice":"Demonstration learning content for interface validation. It is not final MOSCATELLI policy, curriculum or language instruction and must be reviewed before operational use.","sections":[{"heading":"What a useful record preserves","blocks":[{"type":"list","items":["What was decided","Why the decision was necessary","Who owns the next action","Any material constraint or deadline","The source documents or discussion that informed it"]}]},{"heading":"Write for the next reader","blocks":[{"type":"paragraph","text":"A good internal record should make sense to a colleague who was not present. It should be concise enough to scan and complete enough to avoid reconstructing the decision from scattered messages."}]}]}'::jsonb,true,'2026-08-13') on conflict (id) do update set slug=excluded.slug,content_type=excluded.content_type,category_slug=excluded.category_slug,title=excluded.title,summary=excluded.summary,topic=excluded.topic,status=excluded.status,version=excluded.version,audience=excluded.audience,permissions=excluded.permissions,keywords=excluded.keywords,reading_minutes=excluded.reading_minutes,metadata=excluded.metadata,document=excluded.document,is_demo=excluded.is_demo,published_at=excluded.published_at,updated_at=now();
insert into public.atlas_content (id,slug,content_type,category_slug,title,summary,topic,status,version,audience,permissions,keywords,reading_minutes,metadata,document,is_demo,published_at) values ('lesson.communication-basics','communication-basics','academia-lesson','people','Internal communication basics','Use a calm, precise structure for internal updates, requests and handovers.','Communication standards','current','0.1-demo','["Internal learners"]'::jsonb,'["internal"]'::jsonb,'["communication","handover","update","request","team"]'::jsonb,22,'{"id":"lesson.communication-basics","slug":"communication-basics","type":"academia-lesson","courseSlug":"moscatelli-onboarding","moduleId":"working-practice","order":4,"category":"people","topic":"Communication standards","eyebrow":"Academia lesson","title":"Internal communication basics","summary":"Use a calm, precise structure for internal updates, requests and handovers.","keywords":["communication","handover","update","request","team"],"estimatedMinutes":22,"readingMinutes":22,"requirement":"required","acknowledgementRequired":false,"owner":"Academia","approver":"Founder","version":"0.1-demo","publishedDate":"2026-08-13","lastReviewed":"2026-08-13","nextReview":"2026-10-13","languageStatus":"English demonstration","status":"current","audience":["Internal learners"],"permissions":["internal"],"demo":true}'::jsonb,'{"id":"lesson.communication-basics","slug":"communication-basics","type":"academia-lesson","courseSlug":"moscatelli-onboarding","moduleId":"working-practice","order":4,"category":"people","topic":"Communication standards","eyebrow":"Academia lesson","title":"Internal communication basics","summary":"Use a calm, precise structure for internal updates, requests and handovers.","keywords":["communication","handover","update","request","team"],"estimatedMinutes":22,"readingMinutes":22,"requirement":"required","acknowledgementRequired":false,"owner":"Academia","approver":"Founder","version":"0.1-demo","publishedDate":"2026-08-13","lastReviewed":"2026-08-13","nextReview":"2026-10-13","languageStatus":"English demonstration","status":"current","audience":["Internal learners"],"permissions":["internal"],"demo":true,"contentNotice":"Demonstration learning content for interface validation. It is not final MOSCATELLI policy, curriculum or language instruction and must be reviewed before operational use.","sections":[{"heading":"Structure before style","blocks":[{"type":"procedure","steps":[{"title":"State the point","text":"Open with the decision, request or material update."},{"title":"Add only useful context","text":"Include the facts another person needs to respond correctly."},{"title":"Make ownership visible","text":"If an action is required, state who is expected to do what and by when."}]}]},{"heading":"Avoid ambiguity","blocks":[{"type":"paragraph","text":"Politeness should not obscure the request. A composed MOSCATELLI message can still be explicit about ownership, timing and the decision needed."}]}]}'::jsonb,true,'2026-08-13') on conflict (id) do update set slug=excluded.slug,content_type=excluded.content_type,category_slug=excluded.category_slug,title=excluded.title,summary=excluded.summary,topic=excluded.topic,status=excluded.status,version=excluded.version,audience=excluded.audience,permissions=excluded.permissions,keywords=excluded.keywords,reading_minutes=excluded.reading_minutes,metadata=excluded.metadata,document=excluded.document,is_demo=excluded.is_demo,published_at=excluded.published_at,updated_at=now();
insert into public.atlas_content (id,slug,content_type,category_slug,title,summary,topic,status,version,audience,permissions,keywords,reading_minutes,metadata,document,is_demo,published_at) values ('lesson.tone-of-voice-foundation','tone-of-voice-foundation','academia-lesson','brand','Tone of voice · Foundation','Recognise the difference between restrained confidence and language that feels inflated, generic or over-written.','Tone of voice','current','0.1-demo','["Internal learners"]'::jsonb,'["internal"]'::jsonb,'["brand","tone","voice","writing","language"]'::jsonb,22,'{"id":"lesson.tone-of-voice-foundation","slug":"tone-of-voice-foundation","type":"academia-lesson","courseSlug":"brand-foundations","moduleId":"voice","order":1,"category":"brand","topic":"Tone of voice","eyebrow":"Academia lesson","title":"Tone of voice · Foundation","summary":"Recognise the difference between restrained confidence and language that feels inflated, generic or over-written.","keywords":["brand","tone","voice","writing","language"],"estimatedMinutes":22,"readingMinutes":22,"requirement":"required","acknowledgementRequired":true,"owner":"Academia","approver":"Founder","version":"0.1-demo","publishedDate":"2026-08-13","lastReviewed":"2026-08-13","nextReview":"2026-10-13","languageStatus":"English demonstration","status":"current","audience":["Internal learners"],"permissions":["internal"],"demo":true}'::jsonb,'{"id":"lesson.tone-of-voice-foundation","slug":"tone-of-voice-foundation","type":"academia-lesson","courseSlug":"brand-foundations","moduleId":"voice","order":1,"category":"brand","topic":"Tone of voice","eyebrow":"Academia lesson","title":"Tone of voice · Foundation","summary":"Recognise the difference between restrained confidence and language that feels inflated, generic or over-written.","keywords":["brand","tone","voice","writing","language"],"estimatedMinutes":22,"readingMinutes":22,"requirement":"required","acknowledgementRequired":true,"owner":"Academia","approver":"Founder","version":"0.1-demo","publishedDate":"2026-08-13","lastReviewed":"2026-08-13","nextReview":"2026-10-13","languageStatus":"English demonstration","status":"current","audience":["Internal learners"],"permissions":["internal"],"demo":true,"contentNotice":"Demonstration learning content for interface validation. It is not final MOSCATELLI policy, curriculum or language instruction and must be reviewed before operational use.","sections":[{"heading":"The underlying principle","blocks":[{"type":"paragraph","text":"MOSCATELLI language should make precision feel effortless. It should not depend on superlatives, manufactured mystique or repeated claims of luxury to create stature."}]},{"heading":"A useful editing pass","blocks":[{"type":"list","items":["Remove claims that cannot be demonstrated.","Prefer one precise noun or verb over stacked adjectives.","Keep institutional writing calm even when the subject is important.","Allow product, material and context to carry prestige."]}]}]}'::jsonb,true,'2026-08-13') on conflict (id) do update set slug=excluded.slug,content_type=excluded.content_type,category_slug=excluded.category_slug,title=excluded.title,summary=excluded.summary,topic=excluded.topic,status=excluded.status,version=excluded.version,audience=excluded.audience,permissions=excluded.permissions,keywords=excluded.keywords,reading_minutes=excluded.reading_minutes,metadata=excluded.metadata,document=excluded.document,is_demo=excluded.is_demo,published_at=excluded.published_at,updated_at=now();
insert into public.atlas_content (id,slug,content_type,category_slug,title,summary,topic,status,version,audience,permissions,keywords,reading_minutes,metadata,document,is_demo,published_at) values ('lesson.product-naming-foundation','product-naming-foundation','academia-lesson','products-and-quality','Product naming · Foundation','Understand the early naming discipline used to keep product language coherent and reviewable.','Product naming','current','0.1-demo','["Internal learners"]'::jsonb,'["internal"]'::jsonb,'["product","naming","name","collection","standard"]'::jsonb,18,'{"id":"lesson.product-naming-foundation","slug":"product-naming-foundation","type":"academia-lesson","courseSlug":"brand-foundations","moduleId":"voice","order":2,"category":"products-and-quality","topic":"Product naming","eyebrow":"Academia lesson","title":"Product naming · Foundation","summary":"Understand the early naming discipline used to keep product language coherent and reviewable.","keywords":["product","naming","name","collection","standard"],"estimatedMinutes":18,"readingMinutes":18,"requirement":"required","acknowledgementRequired":false,"owner":"Academia","approver":"Founder","version":"0.1-demo","publishedDate":"2026-08-13","lastReviewed":"2026-08-13","nextReview":"2026-10-13","languageStatus":"English demonstration","status":"current","audience":["Internal learners"],"permissions":["internal"],"demo":true}'::jsonb,'{"id":"lesson.product-naming-foundation","slug":"product-naming-foundation","type":"academia-lesson","courseSlug":"brand-foundations","moduleId":"voice","order":2,"category":"products-and-quality","topic":"Product naming","eyebrow":"Academia lesson","title":"Product naming · Foundation","summary":"Understand the early naming discipline used to keep product language coherent and reviewable.","keywords":["product","naming","name","collection","standard"],"estimatedMinutes":18,"readingMinutes":18,"requirement":"required","acknowledgementRequired":false,"owner":"Academia","approver":"Founder","version":"0.1-demo","publishedDate":"2026-08-13","lastReviewed":"2026-08-13","nextReview":"2026-10-13","languageStatus":"English demonstration","status":"current","audience":["Internal learners"],"permissions":["internal"],"demo":true,"contentNotice":"Demonstration learning content for interface validation. It is not final MOSCATELLI policy, curriculum or language instruction and must be reviewed before operational use.","sections":[{"heading":"Naming is a system","blocks":[{"type":"paragraph","text":"Product names should work as a family rather than as isolated creative exercises. A name must be distinctive enough to identify the object while remaining compatible with the wider house vocabulary."}]},{"heading":"Before approval","blocks":[{"type":"list","items":["Check the name against existing product and project names.","Confirm spelling, accents and intended pronunciation.","Record the approved form once a decision is made."]}]}]}'::jsonb,true,'2026-08-13') on conflict (id) do update set slug=excluded.slug,content_type=excluded.content_type,category_slug=excluded.category_slug,title=excluded.title,summary=excluded.summary,topic=excluded.topic,status=excluded.status,version=excluded.version,audience=excluded.audience,permissions=excluded.permissions,keywords=excluded.keywords,reading_minutes=excluded.reading_minutes,metadata=excluded.metadata,document=excluded.document,is_demo=excluded.is_demo,published_at=excluded.published_at,updated_at=now();
insert into public.atlas_content (id,slug,content_type,category_slug,title,summary,topic,status,version,audience,permissions,keywords,reading_minutes,metadata,document,is_demo,published_at) values ('lesson.photography-review-foundation','photography-review-foundation','academia-lesson','brand','Photography review · Foundation','A concise first review of image suitability before detailed creative approval.','Photography','current','0.1-demo','["Internal learners"]'::jsonb,'["internal"]'::jsonb,'["photography","image","approval","resolution","brand"]'::jsonb,25,'{"id":"lesson.photography-review-foundation","slug":"photography-review-foundation","type":"academia-lesson","courseSlug":"brand-foundations","moduleId":"image","order":3,"category":"brand","topic":"Photography","eyebrow":"Academia lesson","title":"Photography review · Foundation","summary":"A concise first review of image suitability before detailed creative approval.","keywords":["photography","image","approval","resolution","brand"],"estimatedMinutes":25,"readingMinutes":25,"requirement":"optional","acknowledgementRequired":false,"owner":"Academia","approver":"Founder","version":"0.1-demo","publishedDate":"2026-08-13","lastReviewed":"2026-08-13","nextReview":"2026-10-13","languageStatus":"English demonstration","status":"current","audience":["Internal learners"],"permissions":["internal"],"demo":true}'::jsonb,'{"id":"lesson.photography-review-foundation","slug":"photography-review-foundation","type":"academia-lesson","courseSlug":"brand-foundations","moduleId":"image","order":3,"category":"brand","topic":"Photography","eyebrow":"Academia lesson","title":"Photography review · Foundation","summary":"A concise first review of image suitability before detailed creative approval.","keywords":["photography","image","approval","resolution","brand"],"estimatedMinutes":25,"readingMinutes":25,"requirement":"optional","acknowledgementRequired":false,"owner":"Academia","approver":"Founder","version":"0.1-demo","publishedDate":"2026-08-13","lastReviewed":"2026-08-13","nextReview":"2026-10-13","languageStatus":"English demonstration","status":"current","audience":["Internal learners"],"permissions":["internal"],"demo":true,"contentNotice":"Demonstration learning content for interface validation. It is not final MOSCATELLI policy, curriculum or language instruction and must be reviewed before operational use.","sections":[{"heading":"Technical before aesthetic","blocks":[{"type":"paragraph","text":"Confirm that the image is technically usable before spending time on detailed creative judgement. Resolution, crop flexibility, colour integrity and source-file quality should be known first."}]},{"heading":"Then judge the image as MOSCATELLI","blocks":[{"type":"list","items":["Does the image feel controlled rather than busy?","Is the product or subject represented truthfully?","Does the light support material and form?","Would the image remain credible alongside the rest of the house?"]}]}]}'::jsonb,true,'2026-08-13') on conflict (id) do update set slug=excluded.slug,content_type=excluded.content_type,category_slug=excluded.category_slug,title=excluded.title,summary=excluded.summary,topic=excluded.topic,status=excluded.status,version=excluded.version,audience=excluded.audience,permissions=excluded.permissions,keywords=excluded.keywords,reading_minutes=excluded.reading_minutes,metadata=excluded.metadata,document=excluded.document,is_demo=excluded.is_demo,published_at=excluded.published_at,updated_at=now();
