,"requirement":"required","acknowledgementRequired":true,"owner":"Academia","approver":"Founder","version":"0.1-demo","publishedDate":"2026-08-13","lastReviewed":"2026-08-13","nextReview":"2026-10-13","languageStatus":"English demonstration","status":"current","audience":["Internal learners"],"permissions":["internal"],"demo":true,"contentNotice":"Demonstration learning content for interface validation. It is not final MOSCATELLI policy, curriculum or language instruction and must be reviewed before operational use.","sections":[{"heading":"What to establish first","blocks":[{"type":"list","items":["Supplier identity and quotation date","Currency","Product or service description","Quantity and minimum order requirements","Unit and total pricing","Payment terms","Lead time and validity period"]}]},{"heading":"Do not fill gaps by assumption","blocks":[{"type":"paragraph","text":"If a commercial term is absent or ambiguous, the correct next step is clarification. Silence in a quotation should not be converted into a favourable assumption in the internal record."}]}]}'::jsonb,true,'2026-08-13') on conflict (id) do update set slug=excluded.slug,content_type=excluded.content_type,category_slug=excluded.category_slug,title=excluded.title,summary=excluded.summary,topic=excluded.topic,status=excluded.status,version=excluded.version,audience=excluded.audience,permissions=excluded.permissions,keywords=excluded.keywords,reading_minutes=excluded.reading_minutes,metadata=excluded.metadata,document=excluded.document,is_demo=excluded.is_demo,published_at=excluded.published_at,updated_at=now();
insert into public.atlas_content (id,slug,content_type,category_slug,title,summary,topic,status,version,audience,permissions,keywords,reading_minutes,metadata,document,is_demo,published_at) values ('lesson.sample-review-foundation','sample-review-foundation','academia-lesson','products-and-quality','Sample review · Foundation','A controlled first pass for physical samples that keeps evidence, observations and revisions separate.','Sample stages','current','0.1-demo','["Internal learners"]'::jsonb,'["internal"]'::jsonb,'["sample","prototype","quality","review","supplier"]'::jsonb,25,'{"id":"lesson.sample-review-foundation","slug":"sample-review-foundation","type":"academia-lesson","courseSlug":"supplier-procedures","moduleId":"samples","order":2,"category":"products-and-quality","topic":"Sample stages","eyebrow":"Academia lesson","title":"Sample review · Foundation","summary":"A controlled first pass for physical samples that keeps evidence, observations and revisions separate.","keywords":["sample","prototype","quality","review","supplier"],"estimatedMinutes":25,"readingMinutes":25,"requirement":"required","acknowledgementRequired":false,"owner":"Academia","approver":"Founder","version":"0.1-demo","publishedDate":"2026-08-13","lastReviewed":"2026-08-13","nextReview":"2026-10-13","languageStatus":"English demonstration","status":"current","audience":["Internal learners"],"permissions":["internal"],"demo":true}'::jsonb,'{"id":"lesson.sample-review-foundation","slug":"sample-review-foundation","type":"academia-lesson","courseSlug":"supplier-procedures","moduleId":"samples","order":2,"category":"products-and-quality","topic":"Sample stages","eyebrow":"Academia lesson","title":"Sample review · Foundation","summary":"A controlled first pass for physical samples that keeps evidence, observations and revisions separate.","keywords":["sample","prototype","quality","review","supplier"],"estimatedMinutes":25,"readingMinutes":25,"requirement":"required","acknowledgementRequired":false,"owner":"Academia","approver":"Founder","version":"0.1-demo","publishedDate":"2026-08-13","lastReviewed":"2026-08-13","nextReview":"2026-10-13","languageStatus":"English demonstration","status":"current","audience":["Internal learners"],"permissions":["internal"],"demo":true,"contentNotice":"Demonstration learning content for interface validation. It is not final MOSCATELLI policy, curriculum or language instruction and must be reviewed before operational use.","sections":[{"heading":"Review in a repeatable order","blocks":[{"type":"procedure","steps":[{"title":"Received condition","text":"Document packaging and any transit issue before altering the sample."},{"title":"Specification","text":"Compare measurable details with the version that was requested."},{"title":"Construction and material","text":"Record observations as facts before proposing revisions."},{"title":"Decision","text":"State whether the sample is approved, rejected or requires a new revision."}]}]},{"heading":"Keep the trail intact","blocks":[{"type":"paragraph","text":"A later reviewer should be able to distinguish the sample that arrived, the observations made on it and the revision that was subsequently requested."}]}]}'::jsonb,true,'2026-08-13') on conflict (id) do update set slug=excluded.slug,content_type=excluded.content_type,category_slug=excluded.category_slug,title=excluded.title,summary=excluded.summary,topic=excluded.topic,status=excluded.status,version=excluded.version,audience=excluded.audience,permissions=excluded.permissions,keywords=excluded.keywords,reading_minutes=excluded.reading_minutes,metadata=excluded.metadata,document=excluded.document,is_demo=excluded.is_demo,published_at=excluded.published_at,updated_at=now();
insert into public.atlas_content (id,slug,content_type,category_slug,title,summary,topic,status,version,audience,permissions,keywords,reading_minutes,metadata,document,is_demo,published_at) values ('lesson.supplier-follow-up-foundation','supplier-follow-up-foundation','academia-lesson','suppliers','Supplier follow-up · Foundation','Handle a missed supplier response without creating noise, losing the decision date or escalating prematurely.','Supplier communication','current','0.1-demo','["Internal learners"]'::jsonb,'["internal"]'::jsonb,'["supplier","vendor","follow-up","delay","communication"]'::jsonb,23,'{"id":"lesson.supplier-follow-up-foundation","slug":"supplier-follow-up-foundation","type":"academia-lesson","courseSlug":"supplier-procedures","moduleId":"samples","order":3,"category":"suppliers","topic":"Supplier communication","eyebrow":"Academia lesson","title":"Supplier follow-up · Foundation","summary":"Handle a missed supplier response without creating noise, losing the decision date or escalating prematurely.","keywords":["supplier","vendor","follow-up","delay","communication"],"estimatedMinutes":23,"readingMinutes":23,"requirement":"optional","acknowledgementRequired":false,"owner":"Academia","approver":"Founder","version":"0.1-demo","publishedDate":"2026-08-13","lastReviewed":"2026-08-13","nextReview":"2026-10-13","languageStatus":"English demonstration","status":"current","audience":["Internal learners"],"permissions":["internal"],"demo":true}'::jsonb,'{"id":"lesson.supplier-follow-up-foundation","slug":"supplier-follow-up-foundation","type":"academia-lesson","courseSlug":"supplier-procedures","moduleId":"samples","order":3,"category":"suppliers","topic":"Supplier communication","eyebrow":"Academia lesson","title":"Supplier follow-up · Foundation","summary":"Handle a missed supplier response without creating noise, losing the decision date or escalating prematurely.","keywords":["supplier","vendor","follow-up","delay","communication"],"estimatedMinutes":23,"readingMinutes":23,"requirement":"optional","acknowledgementRequired":false,"owner":"Academia","approver":"Founder","version":"0.1-demo","publishedDate":"2026-08-13","lastReviewed":"2026-08-13","nextReview":"2026-10-13","languageStatus":"English demonstration","status":"current","audience":["Internal learners"],"permissions":["internal"],"demo":true,"contentNotice":"Demonstration learning content for interface validation. It is not final MOSCATELLI policy, curriculum or language instruction and must be reviewed before operational use.","sections":[{"heading":"One clear follow-up is better than repeated chasing","blocks":[{"type":"paragraph","text":"Restate the pending item, the earlier expectation and the date by which MOSCATELLI now needs a response. Then record the next check point instead of sending repeated messages without a decision threshold."}]},{"heading":"Escalate on impact","blocks":[{"type":"list","items":["A production or sample slot may be lost.","A payment or commercial commitment is approaching.","A launch or internal milestone is now materially at risk."]}]}]}'::jsonb,true,'2026-08-13') on conflict (id) do update set slug=excluded.slug,content_type=excluded.content_type,category_slug=excluded.category_slug,title=excluded.title,summary=excluded.summary,topic=excluded.topic,status=excluded.status,version=excluded.version,audience=excluded.audience,permissions=excluded.permissions,keywords=excluded.keywords,reading_minutes=excluded.reading_minutes,metadata=excluded.metadata,document=excluded.document,is_demo=excluded.is_demo,published_at=excluded.published_at,updated_at=now();
insert into public.atlas_content (id,slug,content_type,category_slug,title,summary,topic,status,version,audience,permissions,keywords,reading_minutes,metadata,document,is_demo,published_at) values ('lesson.italian-introductions','italian-introductions','academia-lesson','people','Presentarsi con precisione','Use a small set of natural structures to introduce yourself and your role without overloading the first exchange.','Development','current','0.1-demo','["Internal learners"]'::jsonb,'["internal"]'::jsonb,'["Italian","introductions","presentarsi","role","language"]'::jsonb,20,'{"id":"lesson.italian-introductions","slug":"italian-introductions","type":"academia-lesson","courseSlug":"italian-foundation","moduleId":"presence","order":1,"category":"people","topic":"Development","eyebrow":"Academia lesson","title":"Presentarsi con precisione","summary":"Use a small set of natural structures to introduce yourself and your role without overloading the first exchange.","keywords":["Italian","introductions","presentarsi","role","language"],"estimatedMinutes":20,"readingMinutes":20,"requirement":"required","acknowledgementRequired":false,"owner":"Academia","approver":"Founder","version":"0.1-demo","publishedDate":"2026-08-13","lastReviewed":"2026-08-13","nextReview":"2026-10-13","languageStatus":"English demonstration","status":"current","audience":["Internal learners"],"permissions":["internal"],"demo":true}'::jsonb,'{"id":"lesson.italian-introductions","slug":"italian-introductions","type":"academia-lesson","courseSlug":"italian-foundation","moduleId":"presence","order":1,"category":"people","topic":"Development","eyebrow":"Academia lesson","title":"Presentarsi con precisione","summary":"Use a small set of natural structures to introduce yourself and your role without overloading the first exchange.","keywords":["Italian","introductions","presentarsi","role","language"],"estimatedMinutes":20,"readingMinutes":20,"requirement":"required","acknowledgementRequired":false,"owner":"Academia","approver":"Founder","version":"0.1-demo","publishedDate":"2026-08-13","lastReviewed":"2026-08-13","nextReview":"2026-10-13","languageStatus":"English demonstration","status":"current","audience":["Internal learners"],"permissions":["internal"],"demo":true,"contentNotice":"Demonstration learning content for interface validation. It is not final MOSCATELLI policy, curriculum or language instruction and must be reviewed before operational use.","sections":[{"heading":"Core structures","blocks":[{"type":"list","items":["Mi chiamo … — My name is …","Lavoro con MOSCATELLI. — I work with MOSCATELLI.","Mi occupo di … — I am responsible for / I deal with …","Piacere di conoscerti. — Nice to meet you. (informal)","Piacere di conoscerla. — Nice to meet you. (formal)"]}]},{"heading":"Practice","blocks":[{"type":"paragraph","text":"Combine only the information the situation requires: name, organisation and one clear description of your role. The goal is comfortable, intelligible speech rather than a memorised biography."}]}]}'::jsonb,true,'2026-08-13') on conflict (id) do update set slug=excluded.slug,content_type=excluded.content_type,category_slug=excluded.category_slug,title=excluded.title,summary=excluded.summary,topic=excluded.topic,status=excluded.status,version=excluded.version,audience=excluded.audience,permissions=excluded.permissions,keywords=excluded.keywords,reading_minutes=excluded.reading_minutes,metadata=excluded.metadata,document=excluded.document,is_demo=excluded.is_demo,published_at=excluded.published_at,updated_at=now();
insert into public.atlas_content (id,slug,content_type,category_slug,title,summary,topic,status,version,audience,permissions,keywords,reading_minutes,metadata,document,is_demo,published_at) values ('lesson.italian-courtesy','italian-courtesy','academia-lesson','people','Cortesia professionale','Build a compact set of polite forms for requests, thanks and clarification in ordinary professional conversation.','Development','current','0.1-demo','["Internal learners"]'::jsonb,'["internal"]'::jsonb,'["Italian","courtesy","please","thank you","clarification"]'::jsonb,20,'{"id":"lesson.italian-courtesy","slug":"italian-courtesy","type":"academia-lesson","courseSlug":"italian-foundation","moduleId":"presence","order":2,"category":"people","topic":"Development","eyebrow":"Academia lesson","title":"Cortesia professionale","summary":"Build a compact set of polite forms for requests, thanks and clarification in ordinary professional conversation.","keywords":["Italian","courtesy","please","thank you","clarification"],"estimatedMinutes":20,"readingMinutes":20,"requirement":"required","acknowledgementRequired":true,"owner":"Academia","approver":"Founder","version":"0.1-demo","publishedDate":"2026-08-13","lastReviewed":"2026-08-13","nextReview":"2026-10-13","languageStatus":"English demonstration","status":"current","audience":["Internal learners"],"permissions":["internal"],"demo":true}'::jsonb,'{"id":"lesson.italian-courtesy","slug":"italian-courtesy","type":"academia-lesson","courseSlug":"italian-foundation","moduleId":"presence","order":2,"category":"people","topic":"Development","eyebrow":"Academia lesson","title":"Cortesia professionale","summary":"Build a compact set of polite forms for requests, thanks and clarification in ordinary professional conversation.","keywords":["Italian","courtesy","please","thank you","clarification"],"estimatedMinutes":20,"readingMinutes":20,"requirement":"required","acknowledgementRequired":true,"owner":"Academia","approver":"Founder","version":"0.1-demo","publishedDate":"2026-08-13","lastReviewed":"2026-08-13","nextReview":"2026-10-13","languageStatus":"English demonstration","status":"current","audience":["Internal learners"],"permissions":["internal"],"demo":true,"contentNotice":"Demonstration learning content for interface validation. It is not final MOSCATELLI policy, curriculum or language instruction and must be reviewed before operational use.","sections":[{"heading":"Useful forms","blocks":[{"type":"list","items":["Per favore. — Please.","Grazie mille. — Thank you very much.","Potresti ripetere? — Could you repeat? (informal)","Potrebbe ripetere? — Could you repeat? (formal)","Non ho capito bene. — I did not understand clearly.","Va bene, grazie. — That is fine, thank you."]}]},{"heading":"Register","blocks":[{"type":"paragraph","text":"Italian changes according to familiarity and formality. This preview introduces both informal and formal forms, but a real curriculum should define the preferred register for specific MOSCATELLI situations."}]}]}'::jsonb,true,'2026-08-13') on conflict (id) do update set slug=excluded.slug,content_type=excluded.content_type,category_slug=excluded.category_slug,title=excluded.title,summary=excluded.summary,topic=excluded.topic,status=excluded.status,version=excluded.version,audience=excluded.audience,permissions=excluded.permissions,keywords=excluded.keywords,reading_minutes=excluded.reading_minutes,metadata=excluded.metadata,document=excluded.document,is_demo=excluded.is_demo,published_at=excluded.published_at,updated_at=now();
