iewed":"2026-08-13","nextReview":"2026-10-13","languageStatus":"English demonstration","status":"current","audience":["Internal learners"],"permissions":["internal"],"demo":true,"contentNotice":"Demonstration learning content for interface validation. It is not final MOSCATELLI policy, curriculum or language instruction and must be reviewed before operational use.","sections":[{"heading":"Date pattern","blocks":[{"type":"paragraph","text":"Italian commonly states the day before the month: 13 agosto 2026. For the first day of a month, primo is common: il primo settembre."}]},{"heading":"Practice set","blocks":[{"type":"list","items":["13 agosto — 13 August","24 aprile — 24 April","trenta — thirty","cento — one hundred","mille — one thousand","duecentocinquanta euro — two hundred and fifty euros"]}]}]}'::jsonb,true,'2026-08-13') on conflict (id) do update set slug=excluded.slug,content_type=excluded.content_type,category_slug=excluded.category_slug,title=excluded.title,summary=excluded.summary,topic=excluded.topic,status=excluded.status,version=excluded.version,audience=excluded.audience,permissions=excluded.permissions,keywords=excluded.keywords,reading_minutes=excluded.reading_minutes,metadata=excluded.metadata,document=excluded.document,is_demo=excluded.is_demo,published_at=excluded.published_at,updated_at=now();
insert into public.atlas_content (id,slug,content_type,category_slug,title,summary,topic,status,version,audience,permissions,keywords,reading_minutes,metadata,document,is_demo,published_at) values ('lesson.italian-times-scheduling','italian-times-scheduling','academia-lesson','people','Orari e appuntamenti','Use simple structures for proposing, confirming and changing times.','Development','current','0.1-demo','["Internal learners"]'::jsonb,'["internal"]'::jsonb,'["Italian","time","schedule","appointment","calendar"]'::jsonb,25,'{"id":"lesson.italian-times-scheduling","slug":"italian-times-scheduling","type":"academia-lesson","courseSlug":"italian-foundation","moduleId":"coordination","order":4,"category":"people","topic":"Development","eyebrow":"Academia lesson","title":"Orari e appuntamenti","summary":"Use simple structures for proposing, confirming and changing times.","keywords":["Italian","time","schedule","appointment","calendar"],"estimatedMinutes":25,"readingMinutes":25,"requirement":"required","acknowledgementRequired":false,"owner":"Academia","approver":"Founder","version":"0.1-demo","publishedDate":"2026-08-13","lastReviewed":"2026-08-13","nextReview":"2026-10-13","languageStatus":"English demonstration","status":"current","audience":["Internal learners"],"permissions":["internal"],"demo":true}'::jsonb,'{"id":"lesson.italian-times-scheduling","slug":"italian-times-scheduling","type":"academia-lesson","courseSlug":"italian-foundation","moduleId":"coordination","order":4,"category":"people","topic":"Development","eyebrow":"Academia lesson","title":"Orari e appuntamenti","summary":"Use simple structures for proposing, confirming and changing times.","keywords":["Italian","time","schedule","appointment","calendar"],"estimatedMinutes":25,"readingMinutes":25,"requirement":"required","acknowledgementRequired":false,"owner":"Academia","approver":"Founder","version":"0.1-demo","publishedDate":"2026-08-13","lastReviewed":"2026-08-13","nextReview":"2026-10-13","languageStatus":"English demonstration","status":"current","audience":["Internal learners"],"permissions":["internal"],"demo":true,"contentNotice":"Demonstration learning content for interface validation. It is not final MOSCATELLI policy, curriculum or language instruction and must be reviewed before operational use.","sections":[{"heading":"Core forms","blocks":[{"type":"list","items":["Alle nove. — At nine.","Verso le tre. — Around three.","Domani mattina. — Tomorrow morning.","Va bene per le quattro? — Is four o’clock okay?","Possiamo spostare l’appuntamento? — Can we move the appointment?","Confermo per venerdì alle dieci. — I confirm for Friday at ten."]}]},{"heading":"Accuracy matters","blocks":[{"type":"paragraph","text":"For operational coordination, repeat the day and time in the confirmation rather than relying on context. This reduces misunderstandings while the learner is still building confidence."}]}]}'::jsonb,true,'2026-08-13') on conflict (id) do update set slug=excluded.slug,content_type=excluded.content_type,category_slug=excluded.category_slug,title=excluded.title,summary=excluded.summary,topic=excluded.topic,status=excluded.status,version=excluded.version,audience=excluded.audience,permissions=excluded.permissions,keywords=excluded.keywords,reading_minutes=excluded.reading_minutes,metadata=excluded.metadata,document=excluded.document,is_demo=excluded.is_demo,published_at=excluded.published_at,updated_at=now();
